import { Test, TestingModule } from '@nestjs/testing';
import { getRepositoryToken } from '@nestjs/typeorm';
import { Repository, EntityManager } from 'typeorm';
import { BOMChangeLog } from '../bom_change_log/bom-change-log.entity';
import { BOMChangeLogService } from '../bom_change_log/bom-change-log.service';
import { BOMComponent } from './bom-component.entity';
import { BOMComponentService } from './bom-component.service';
import { BOMComponentCreateRequestDTO } from './dtos/bom-component-create-request.dto';
import { AppLogger } from '@/common/logger/app-logger';

jest.mock('@/common/logger/app-logger');

describe('BOMComponentService', () => {
  let service: BOMComponentService;
  let bomComponentRepo: jest.Mocked<Repository<BOMComponent>>;
  let bomChangeLogService: jest.Mocked<BOMChangeLogService>;

  beforeEach(async () => {
    const module: TestingModule = await Test.createTestingModule({
      providers: [
        BOMComponentService,
        {
          provide: getRepositoryToken(BOMComponent),
          useValue: {
            create: jest.fn(),
            save: jest.fn(),
          },
        },
        {
          provide: BOMChangeLogService,
          useValue: {
            createChangeLog: jest.fn(),
          },
        },
        AppLogger,
      ],
    }).compile();

    service = module.get<BOMComponentService>(BOMComponentService);
    bomComponentRepo = module.get(getRepositoryToken(BOMComponent));
    bomChangeLogService = module.get(BOMChangeLogService);
  });

  afterEach(() => {
    jest.clearAllMocks();
  });

  describe('createBOMComponent', () => {
    const bomComponentInput: BOMComponentCreateRequestDTO = {
      bomId: 123,
      materialCategory: 'L',
      materialId: 'COMP_A123',
      plant: 1146,
      positionNr: 1,
      quantity: 0.25,
      unitOfMeasure: 'KG',
    };

    it('should create and return a new BOMComponent (default repo)', async () => {
      const savedBOMComponent = { id: 1, ...bomComponentInput } as BOMComponent;

      bomComponentRepo.create.mockReturnValue(savedBOMComponent);
      bomComponentRepo.save.mockResolvedValue(savedBOMComponent);
      bomChangeLogService.createChangeLog.mockResolvedValue({} as BOMChangeLog); // We do not care here about the output of createChangeLog

      const result = await service.createBOMComponent(bomComponentInput);

      expect(bomComponentRepo.create).toHaveBeenCalledWith(bomComponentInput);
      expect(bomComponentRepo.save).toHaveBeenCalledWith(savedBOMComponent);
      expect(bomChangeLogService.createChangeLog).toHaveBeenCalledWith(
        {
          entityId: savedBOMComponent.id,
          entityType: 'bom_component',
          operation: 'create',
          plant: savedBOMComponent.plant,
          source: undefined,
        },
        undefined,
      );

      expect(result).toEqual(savedBOMComponent);
    });

    it('should use EntityManager when provided', async () => {
      const savedBOMComponent = { id: 1, ...bomComponentInput } as BOMComponent;

      const managerRepo: jest.Mocked<Repository<BOMComponent>> = {
        create: jest.fn().mockReturnValue(savedBOMComponent),
        save: jest.fn().mockResolvedValue(savedBOMComponent),
      } as unknown as jest.Mocked<Repository<BOMComponent>>;

      const mockManager: Partial<EntityManager> = {
        getRepository: jest.fn().mockReturnValue(managerRepo),
      };

      bomChangeLogService.createChangeLog.mockResolvedValue({} as BOMChangeLog); // We do not care here about the output of createChangeLog

      const result = await service.createBOMComponent(
        bomComponentInput,
        mockManager as EntityManager,
        'unit-test',
      );

      expect(mockManager.getRepository).toHaveBeenCalledWith(BOMComponent);
      expect(managerRepo.create).toHaveBeenCalledWith(bomComponentInput);
      expect(managerRepo.save).toHaveBeenCalledWith(savedBOMComponent);
      expect(bomChangeLogService.createChangeLog).toHaveBeenCalledWith(
        {
          entityId: savedBOMComponent.id,
          entityType: 'bom_component',
          operation: 'create',
          plant: savedBOMComponent.plant,
          source: 'unit-test',
        },
        mockManager,
      );

      expect(result).toEqual(savedBOMComponent);
    });

    it('should throw InternalServerErrorException if creation fails', async () => {
      const error = new Error('DB error');
      const savedBOMComponent = { id: 1, ...bomComponentInput } as BOMComponent;
      bomComponentRepo.create.mockReturnValue(savedBOMComponent);
      bomComponentRepo.save.mockRejectedValue(error);

      await expect(
        service.createBOMComponent(bomComponentInput),
      ).rejects.toThrow('Failed to create BOM Component');

      expect(bomComponentRepo.create).toHaveBeenCalledWith(bomComponentInput);
      expect(bomComponentRepo.save).toHaveBeenCalled();
      expect(bomChangeLogService.createChangeLog).not.toHaveBeenCalled();
      expect(service['logger'].error).toHaveBeenCalledWith(
        expect.stringContaining('Failed to create BOM Component'),
        error.stack,
      );
    });
  });
});

import {
  Injectable,
  InternalServerErrorException,
  NotFoundException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { EntityManager, Repository } from 'typeorm';
import { BOMChangeLogService } from '../bom_change_log/bom-change-log.service';
import { BOMComponentCreateRequestDTO } from './dtos/bom-component-create-request.dto';
import { AppLogger } from '@/common/logger/app-logger';

import { BOMComponent } from '@/modules/bom-component/bom-component.entity';

@Injectable()
export class BOMComponentService {
  private readonly logger = new AppLogger(BOMComponentService.name);

  public constructor(
    @InjectRepository(BOMComponent)
    private readonly bomComponentRepo: Repository<BOMComponent>,

    private readonly bomChangeLogService: BOMChangeLogService,
  ) {}

  /**
   * Creates and saves a new BOM component in the database.
   *
   * This method supports both transactional and non-transactional execution:
   * - If an `EntityManager` is provided, the operation is executed within that transaction context.
   * - If no `EntityManager` is provided, the default repository is used.
   *
   * Additionally, after saving the BOM component, this method creates a corresponding
   * BOM change log entry.
   * @param bomComponentInput - The input data required to create the BOM component.
   * @param [manager] - (Optional) A TypeORM `EntityManager` for transactional context.
   * @param [triggerSource] - (Optional) A string indicating the source of the operation (e.g., "unit-test", "import-script", "job").
   * @returns The newly created and saved `BOMComponent` entity.
   * @throws {InternalServerErrorException} If creation or logging fails.
   */
  public async createBOMComponent(
    bomComponentInput: BOMComponentCreateRequestDTO,
    manager?: EntityManager,
    triggerSource?: string,
  ): Promise<BOMComponent> {
    try {
      const repo = manager
        ? manager.getRepository(BOMComponent)
        : this.bomComponentRepo;
      const newBOMComponent = repo.create({ ...bomComponentInput });
      const savedBOMComponent = await repo.save(newBOMComponent);

      // Create new log entry for the saved bom component
      await this.bomChangeLogService.createChangeLog(
        {
          entityId: savedBOMComponent.id,
          entityType: 'bom_component',
          operation: 'create',
          plant: savedBOMComponent.plant,
          source: triggerSource,
          // ChangedFields: Not needed for creation
        },
        manager,
      );

      return savedBOMComponent;
    } catch (error) {
      this.logger.error(
        `Failed to create BOM Component: ${error.message}`,
        error.stack,
      );
      throw new InternalServerErrorException('Failed to create BOM Component');
    }
  }

  /**
   * Updates an existing BOM component with provided changes without tracking or logging.
   * This is a simplified version of updateBOMComponent that only performs the update
   * without creating change log entries.
   * @param componentId - The ID of the BOM component to update
   * @param changes - An object containing the fields to update and their new values
   * @param manager - Optional EntityManager for transaction support
   * @returns The updated BOM component entity
   * @throws {NotFoundException} If the component is not found
   * @throws {InternalServerErrorException} If the update fails
   */
  public async updateBOMComponent(
    componentId: number,
    changes: Partial<BOMComponent>,
    manager?: EntityManager,
  ): Promise<BOMComponent> {
    try {
      const repo = manager
        ? manager.getRepository(BOMComponent)
        : this.bomComponentRepo;

      // Find the component
      const component = await repo.findOne({
        where: { id: componentId },
      });

      if (!component) {
        throw new NotFoundException(
          `BOM Component with ID ${componentId} not found`,
        );
      }

      // Apply changes
      Object.assign(component, changes);

      // Save the updated component
      return await repo.save(component);
    } catch (error) {
      if (error instanceof NotFoundException) {
        throw error;
      }

      this.logger.error(
        `Failed to update BOM Component: ${error.message}`,
        error.stack,
      );
      throw new InternalServerErrorException('Failed to update BOM Component');
    }
  }
}

