  @Column({ type: 'int', name: 'plant', nullable: false })
  public plant: number;

  @Column({ type: 'nvarchar', length: 64, name: 'bom_number', nullable: false })
  public bomNumber: string;

  @Column({
    type: 'nvarchar',
    length: 256,
    name: 'bom_description',
    nullable: true,
  })
  public bomDescription?: string | null;

  @Column({ type: 'datetime', name: 'valid_from', nullable: false })
  public validFrom: Date;

  @Column({ type: 'datetime', name: 'valid_to', nullable: true })
  public validTo?: Date | null;

  @OneToMany(() => BOMComponent, (component) => component.bom)
  public components?: Array<BOMComponent>;
}

