import { TypeOrmModule } from '@nestjs/typeorm';

import { BOMComponentModule } from '../bom-component/bom-component.module';
import { BOMChangeLogModule } from '../bom_change_log/bom-change-log.module';
import { MaterialDTLModule } from '../material-dtl/material-dtl.module';
import { PublishMessageModule } from '@/common/publish-message/publish-message.module';
import { EventHubModule } from '@/config/eventhub/eventhub.module';
