import {
  Injectable,
  InternalServerErrorException,
  NotFoundException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import {
  Repository,
  DataSource,
  EntityManager,
  Raw,
  LessThanOrEqual,
  In,
} from 'typeorm';
import { BOMComponentService } from '../bom-component/bom-component.service';
import { BOMComponentCreateRequestDTO } from '../bom-component/dtos/bom-component-create-request.dto';
import { BOMComponentResponseDTO } from '../bom-component/dtos/bom-component-response.dto';
import { UpdateBOMComponentsRequestDTO } from '../bom-component/dtos/requests/update-bom-components-request.dto';
import { UpdateBOMComponentsResponseDTO } from '../bom-component/dtos/responses/update-bom-components-response.dto';
import { BOMChangeLogService } from '../bom_change_log/bom-change-log.service';
import { MaterialDTLService } from '../material-dtl/material-dtl.service';
import { BOM } from './bom.entity';
import { BOMCreateRequestDTO } from './dtos/bom-create-request.dto';
import { BOMResponseDTO } from './dtos/bom-response.dto';
import { GetBOMQueryParametersDTO } from './dtos/get-bom-query-parameters.dto';
import { GetBOMsResponseDTO } from './dtos/get-boms-response.dto';
import { BOMServiceUtility } from './utils/bom-service.utility';
import { AppLogger } from '@/common/logger/app-logger';
import { Material } from '@/modules/material/material.entity';

@Injectable()
export class BOMService {
  private readonly logger = new AppLogger(BOMService.name);

  public constructor(
    @InjectRepository(BOM)
    private readonly bomRepository: Repository<BOM>,

    private readonly bomComponentService: BOMComponentService,
    private readonly bomChangeLogService: BOMChangeLogService,
    private readonly materialDTLService: MaterialDTLService,

    private readonly dataSource: DataSource,
  ) {}

  /**
   * Creates a new BOM (Bill of Materials) entry in the database.
   * This method supports both transactional and non-transactional execution.
   * If an EntityManager is provided, the change log will be created and saved using the manager (inside the current sql transaction which was opened outside current context).
   * If no manager is provided, the default repository is used (outside any explicit sql transaction).
   * Also creates a BOM change log entry for the creation event.
   * @param bomInput - The data for creating the BOM.
   * @param [manager] - Optional transactional EntityManager; if provided, uses it for DB operations.
   * @param [triggerSource] - Optional source identifier (free text) to log where the change was triggered from.
   * @returns A promise resolving to the newly created BOM entity.
   * @throws {InternalServerErrorException} If the creation or logging process fails.
   */
  public async createBOM(
    bomInput: BOMCreateRequestDTO,
    manager?: EntityManager,
    triggerSource?: string,
  ): Promise<BOM> {
    try {
      const repo = manager ? manager.getRepository(BOM) : this.bomRepository;
      const newBOM = repo.create({ ...bomInput });
      const savedBOM = await repo.save(newBOM);

      // Create new log entry for the saved bom component
      await this.bomChangeLogService.createChangeLog({
        entityId: savedBOM.id,
        entityType: 'bom',
        operation: 'create',
        plant: savedBOM.plant,
        source: triggerSource,
        // ChangedFields: Not needed for creation
      });

      return savedBOM;
    } catch (error) {
      this.logger.error(`Failed to create BOM: ${error.message}`, error.stack);
      throw new InternalServerErrorException('Failed to create BOM');
    }
  }

  /**
   * Creates a new BOM entry and its associated BOM components within a single sql transaction.
   * Also creates BOM change log entries for both the BOM and each BOM component.
   * @param bomInput - The data for creating the BOM.
   * @param componentsInput - An array of data for creating each BOM component.
   * @param [triggerSource] - Optional source identifier (free text) to log where the change was triggered from.
   * @returns A promise resolving to the fully created BOM entity, including its related components.
   * @throws {InternalServerErrorException} If the creation process (BOM, components, or logging) fails.
   */
  public async createBOMWithComponents(
    bomInput: BOMCreateRequestDTO,
    componentsInput: Array<BOMComponentCreateRequestDTO>,
    triggerSource?: string,
  ): Promise<BOM> {
    try {
      return await this.dataSource.transaction(async (manager) => {
        // Create BOM entity as well as BOM Change Logs (handled inside createBOM method)
        const savedBOM = await this.createBOM(bomInput, manager, triggerSource);

        // Create BOMComponents linked to BOM as well as BOM Change Logs (handled inside createBOMComponent method)
        await Promise.all(
          componentsInput.map((compInput) => {
            return this.bomComponentService.createBOMComponent(
              {
                ...compInput,
                bomId: savedBOM.id,
              },
              manager,
              triggerSource,
            );
          }),
        );

        // Reload BOM with components relations
        const bomWithComponents = await manager.findOne(BOM, {
          where: { id: savedBOM.id },
          relations: ['components'],
        });

        if (!bomWithComponents) {
          throw new NotFoundException(
            `BOM with id ${savedBOM.id} not found after creation`,
          );
        }

        return bomWithComponents;
      });
    } catch (error) {
      this.logger.error('Failed to create BOM and components', error.stack);
      throw new InternalServerErrorException(
        'Failed to create BOM and components',
      );
    }
  }

  /**
   * Retrieves a BOM with nested subcomponents recursively based on material ID, validity date, and optional ERP BOM ID.
   * For each component, it checks if it has its own BOM and recursively fetches those subcomponents.
   * @param queryParameters - Parameters for finding the BOM including materialId, validityDate, plant, and includeComponents
   * @returns The BOM with nested components and subcomponents
   * @throws {NotFoundException} If no BOM is found for the given parameters
   * @throws {InternalServerErrorException} If there's an error retrieving the BOM
   */
  public async getBOMWithComponents(
    queryParameters: GetBOMQueryParametersDTO,
  ): Promise<BOMResponseDTO> {
    try {
      const {
        materialId,
        validityDate,
        plant,
        erpBomId,
        includeComponents = true,
      } = queryParameters;

      if (!materialId) {
        throw new NotFoundException('Material ID is required');
      }

      if (!plant) {
        throw new NotFoundException('Plant is required');
      }

      const validityDateTime = validityDate || new Date();

      // Find the BOM for this material
      const bom = await this.findBOMForMaterial(
        plant,
        materialId,
        includeComponents,
        erpBomId,
        validityDateTime,
      );

      if (!bom) {
        throw new NotFoundException(
          `No valid BOM found for material ${materialId} in plant ${plant}${
            erpBomId ? ` with BOM ID ${erpBomId}` : ''
          } at date ${validityDateTime.toISOString()}`,
        );
      }

      // Transform the BOM into the response DTO with nested components
      return await this.buildBOMResponseWithNestedComponents(
        bom,
        includeComponents,
        new Set(), // Empty set for processedBomNumbers
        validityDateTime,
      );
    } catch (error) {
      if (error instanceof NotFoundException) {
        throw error;
      }
      this.logger.error(
        `Failed to retrieve BOM: ${error.message}`,
        error.stack,
      );
      throw new InternalServerErrorException('Failed to retrieve BOM');
    }
  }

  /**
   * Finds a BOM for a given material ID, plant, and validity date.
   * Uses optimized querying to retrieve the valid BOM for the material at the specified date.
   * @param plant - The plant ID
   * @param materialId - The material ID to find the BOM for
   * @param includeComponents - Whether to include component relationships
   * @param erpBomId - Optional specific ERP BOM ID to filter by
   * @param validAtDatetime - The date for which the BOM should be valid
   * @returns The BOM entity with its components, or null if not found
   */
  private async findBOMForMaterial(
    plant: number,
    materialId: string,
    includeComponents: boolean,
    erpBomId?: string,
    validAtDatetime: Date = new Date(),
  ): Promise<BOM | null> {
    try {
      // Build common query conditions for date validity
      const dateValidityCondition = {
        validFrom: LessThanOrEqual(validAtDatetime),
        validTo: Raw((column) => `COALESCE(${column}, :maxDate) > :date`, {
          maxDate: new Date('9999-12-31'),
          date: validAtDatetime,
        }),
      };

      // If a specific ERP BOM ID is provided, look for that BOM directly
      if (erpBomId) {
        this.logger.debug(
          `Looking for specific BOM ${erpBomId} in plant ${plant}`,
        );
        return await this.bomRepository.findOne({
          where: {
            plant,
            bomNumber: erpBomId,
            ...dateValidityCondition,
          },
          relations: includeComponents ? ['components'] : [],
        });
      }

      // Use MaterialDTLService to get the material's BOM number
      const materialBomNumbersMap =
        await this.materialDTLService.getMaterialBomNumbers(
          [materialId],
          plant,
        );

      const bomNumber = materialBomNumbersMap.get(materialId);

      if (!bomNumber) {
        this.logger.warn(
          `No BOM number found for materialId ${materialId} in plant ${plant}`,
        );
        return null;
      }

      // Query for the specific BOM with validity check
      return await this.bomRepository.findOne({
        where: {
          plant,
          bomNumber,
          ...dateValidityCondition,
        },
        relations: includeComponents ? ['components'] : [],
        order: { validFrom: 'DESC' }, // Get the most recent valid BOM
      });
    } catch (error) {
      this.logger.error(
        `Failed to find BOM for material ${materialId} in plant ${plant}: ${error.message}`,
        error.stack,
      );
      // We return null here instead of throwing, because this is an internal helper method
      // The calling method will handle the case when null is returned
      return null;
    }
  }

  /**
   * Builds a complete BOM response with recursively nested components.
   * @param bom - The BOM entity to transform
   * @param includeComponents - Whether to include component relationships
   * @param processedBomNumbers - Set of BOM numbers that have already been processed (to prevent infinite recursion)
   * @param validityDateTime - The date for which the BOM should be valid
   * @returns The transformed BOM response DTO with nested subcomponents
   */
  private async buildBOMResponseWithNestedComponents(
    bom: BOM,
    includeComponents: boolean,
    processedBomNumbers: Set<string> = new Set(),
    validityDateTime: Date = new Date(),
  ): Promise<BOMResponseDTO> {
    // Add current BOM to the set of processed BOMs to prevent infinite recursion
    processedBomNumbers.add(bom.bomNumber);

    // Create the base BOM response
    const response: BOMResponseDTO = {
      erpBomId: bom.bomNumber,
      validFrom: bom.validFrom.toISOString(),
      validTo: bom.validTo ? bom.validTo.toISOString() : null,
      components: [],
    };

    if (!bom.components || bom.components.length === 0) {
      return response;
    }

    // Collect all material IDs from the components to batch fetch leur BOM numbers & material types
    const materialIds = bom.components.map((component) => component.materialId);

    // Use MaterialDTLService to fetch all material BOM numbers in a single operation
    const materialBomNumbersMap =
      await this.materialDTLService.getMaterialBomNumbers(
        materialIds,
        bom.plant,
      );

    // Fetch component types for all materials in one shot
    let componentTypeMap = new Map<string, string>();
    if (materialIds.length > 0) {
      try {
        const materialRepo = this.dataSource.getRepository(Material);
        const materials = await materialRepo.find({
          where: { materialId: In(materialIds) },
          select: ['materialId', 'componentType'],
        });
        componentTypeMap = new Map(
          materials.map((m) => [m.materialId, m.componentType]),
        );
      } catch (error) {
        this.logger.warn(
          `Failed to fetch component types for materials (${materialIds.join(',')}): ${error.message}`,
        );
      }
    }

    // Batch fetch all the subcomponent BOMs that haven't been processed yet
    const subComponentBOMs: Map<string, BOM> = new Map();

    // Get only materials with non-null BOM numbers that haven't been processed yet
    const materialsToProcess = materialIds.filter((id) => {
      const bomNumber = materialBomNumbersMap.get(id);
      return bomNumber && !processedBomNumbers.has(bomNumber);
    });

    if (materialsToProcess.length > 0) {
      // Fetch all subcomponent BOMs in parallel
      const fetchedBOMs = await Promise.all(
        materialsToProcess.map((materialId) => {
          // Use component's plant from the parent BOM, with fallback to the BOM's plant
          const component = bom.components?.find(
            (comp) => comp.materialId === materialId,
          );
          const plant = component?.plant ?? bom.plant;

          // We're specifically looking for the component's BOM, so don't pass the parent BOM number
          return this.findBOMForMaterial(
            plant,
            materialId,
            includeComponents,
            undefined, // No specific erpBomId
            validityDateTime,
          );
        }),
      );

      // Create a lookup map for subcomponent BOMs
      for (const [index, materialId] of materialsToProcess.entries()) {
        const fetchedBOM = fetchedBOMs[index];
        if (fetchedBOM) {
          subComponentBOMs.set(materialId, fetchedBOM);
        }
      }
    }

    // Transform all components with their already-fetched subcomponents
    const componentPromises = bom.components.map(async (component) => {
      // Transform the component itself using utility
      const componentDto =
        BOMServiceUtility.transformComponentToResponseDTO(component);

      // Enrich with componentType from material table (may be undefined)
      componentDto.componentType =
        componentTypeMap.get(component.materialId) ?? null;

      // Check if this component has its own BOM
      const bomNumber = materialBomNumbersMap.get(component.materialId);

      // If this component has its own BOM, add its subcomponents
      // Only process if the BOM number hasn't been processed already (to prevent cycles)
      if (
        bomNumber &&
        !processedBomNumbers.has(bomNumber) &&
        subComponentBOMs.has(component.materialId)
      ) {
        const componentBom = subComponentBOMs.get(component.materialId);

        if (
          componentBom &&
          Array.isArray(componentBom.components) &&
          componentBom.components.length > 0
        ) {
          // Pass the set of processed BOM numbers to prevent infinite recursion
          const nestedResponse =
            await this.buildBOMResponseWithNestedComponents(
              componentBom,
              includeComponents,
              new Set(processedBomNumbers), // Create a new set to avoid modifying the original
              validityDateTime,
            );

          // Add the nested components as subComponents
          componentDto.subComponents = nestedResponse.components.map(
            (c) =>
              ({
                component: c.component,
                componentType: c.componentType ?? null,
                id: c.id,
                itemNumber: c.itemNumber,
                kitmat: c.kitmat,
                materialCategory: c.materialCategory,
                quantity: c.quantity,
                skipBomLevel: c.skipBomLevel,
                uom: c.uom,
                // If this nested component has its own subcomponents, include them too
                ...(c.subComponents && c.subComponents.length > 0
                  ? { subComponents: c.subComponents }
                  : {}),
              }) as BOMComponentResponseDTO,
          );
        }
      }

      return componentDto;
    });

    // Wait for all components to be processed in parallel
    response.components = await Promise.all(componentPromises);

    return response;
  }

  /**
   * Updates properties of BOM components using their direct IDs.
   * @param updateDto - The data containing the components with their IDs and properties to update
   * @returns Response indicating success or failure
   * @throws {NotFoundException} If any component is not found
   * @throws {InternalServerErrorException} If there's an error updating the components
   */
  public async updateBOMComponentsById(
    updateDto: UpdateBOMComponentsRequestDTO,
  ): Promise<UpdateBOMComponentsResponseDTO> {
    try {
      return await this.dataSource.transaction(async (manager) => {
        // Process all component updates in parallel
        await Promise.all(
          updateDto.components.map(async (componentUpdate) => {
            // Extract properties to update (excluding componentId)
            const { componentId, ...propertiesToUpdate } = componentUpdate;

            // Update the component using its ID directly
            await this.bomComponentService.updateBOMComponent(
              componentId,
              propertiesToUpdate,
              manager,
            );
          }),
        );

        return {
          success: true,
          message: 'Component properties updated successfully',
        };
      });
    } catch (error) {
      if (error instanceof NotFoundException) {
        throw error;
      }
      this.logger.error(
        `Failed to update BOM components: ${error.message}`,
        error.stack,
      );
      throw new InternalServerErrorException(
        'Failed to update component properties',
      );
    }
  }

  /**
   * Retrieves a list of BOMs based on bomId and optional validFromDateTime
   * @param bomId - The BOM ID to search for
   * @param plant - The plant code to search in
   * @param validFromDateTime - Optional date to check validity against (defaults to showing all validity periods)
   * @returns List of BOMs with their associated material IDs and validity dates
   * @throws {NotFoundException} If no BOMs are found for the given parameters
   * @throws {InternalServerErrorException} If there's an error retrieving the BOMs
   */
  public async getBOMsByBomId(
    bomId: string,
    plant: number,
    validFromDateTime?: Date,
  ): Promise<GetBOMsResponseDTO> {
    try {
      const queryOptions = {
        where: {
          bomNumber: bomId,
          plant,
        },
        order: {
          plant: 'ASC' as const,
          validFrom: 'DESC' as const,
        },
      };

      // If a specific date is provided, filter BOMs valid at that date
      // Otherwise, return all versions with different validity dates
      if (validFromDateTime) {
        const dateValidityCondition = {
          validFrom: LessThanOrEqual(validFromDateTime),
          validTo: Raw((column) => `COALESCE(${column}, :maxDate) > :date`, {
            maxDate: new Date('9999-12-31'),
            date: validFromDateTime,
          }),
        };

        queryOptions.where = {
          ...queryOptions.where,
          ...dateValidityCondition,
        };
      }

      // Query for BOMs with the specified bomNumber
      const boms = await this.bomRepository.find(queryOptions);

      if (!boms || boms.length === 0) {
        throw new NotFoundException(
          `No BOMs found with BOM ID ${bomId}${
            validFromDateTime
              ? ` valid at date ${validFromDateTime.toISOString()}`
              : ''
          }`,
        );
      }

      // Get material IDs for all these BOMs
      const materialIds = await this.findMaterialsForBOMs(boms);

      // Transform the result into the response DTO with only the required fields
      return {
        boms: boms.map((bom) => ({
          erpBomId: bom.bomNumber,
          materialId: materialIds.get(bom.id) ?? 'Unknown',
          validFrom: bom.validFrom.toISOString(),
          validTo: bom.validTo ? bom.validTo.toISOString() : null,
        })),
      };
    } catch (error) {
      if (error instanceof NotFoundException) {
        throw error;
      }
      this.logger.error(
        `Failed to retrieve BOMs by BOM ID: ${error.message}`,
        error.stack,
      );
      throw new InternalServerErrorException('Failed to retrieve BOMs');
    }
  }

  /**
   * Finds materials associated with a list of BOMs
   * This helper method queries the material-BOM relationship to get the material ID for each BOM
   * @param boms - The list of BOM entities
   * @returns A Map of BOM IDs to material IDs
   */
  private async findMaterialsForBOMs(
    boms: Array<BOM>,
  ): Promise<Map<number, string>> {
    const bomIds = boms.map((bom) => bom.id);
    const result = new Map<number, string>();

    try {
      // Query the material_dtl table to find materials that use these BOM IDs
      // Using snake_case for table and column names as per the database schema
      const materialDtls = await this.dataSource.query(`
        SELECT md.material_id as materialId, md.bom_number as bomNumber, b.id as bomId
        FROM material_dtl md
        JOIN bom b ON md.bom_number = b.bom_number
        WHERE b.id IN (${bomIds.join(',')})
      `);

      // Create a mapping of BOM ID to material ID
      for (const item of materialDtls) {
        result.set(item.bomId, item.materialId);
      }

      return result;
    } catch (error) {
      this.logger.error(
        `Failed to find materials for BOMs: ${error.message}`,
        error.stack,
      );
      // Return empty map on error, this will be handled by the calling method
      return result;
    }
  }
}

import { ApiProperty } from '@nestjs/swagger';
import { Type } from 'class-transformer';
import {
  IsDate,
  IsNotEmpty,
  IsNumber,
  IsOptional,
  IsString,
  Max,
  Min,
} from 'class-validator';

/**
 * Details for creating a new bom record
 * @example {
 * 'plant':1146,
 * 'bomNumber': '00769874',
 * 'description': 'Initial version of BOM with 10 components',
 * 'validFrom': '2025-06-12T00:00:00',
 * 'validTo': '2025-07-12T00:00:00'
 * }
 */
export class BOMCreateRequestDTO {
  @ApiProperty({
    description: 'Plant code, which must consist of exactly 4 digits',
    example: 1146,
    required: true,
  })
  @Type(() => Number)
  @IsNumber()
  @IsNotEmpty()
  @Min(1000)
  @Max(9999)
  public plant: number;

  @ApiProperty({
    description: 'Specifies ERP Bom Number',
    example: '00769874',
    required: true,
  })
  @IsString()
  @IsNotEmpty()
  public bomNumber: string;

  @ApiProperty({
    description: 'Specifies ERP Bom Number description',
    example: 'Initial version of BOM with 10 components',
    required: false,
  })
  @IsOptional()
  @IsString()
  @IsNotEmpty()
  public description?: string;

  @ApiProperty({
    description:
      'Specifies the start date and time of the validity (ISO format)',
    example: '2025-06-12T00:00:00',
    required: true,
  })
  @IsNotEmpty()
  @Type(() => Date)
  @IsDate()
  public validFrom: Date;

  @ApiProperty({
    description: 'Specifies the end date and time of the validity (ISO format)',
    example: '2025-06-12T00:00:00',
    required: false,
  })
  @IsOptional()
  @Type(() => Date)
  @IsDate()
  public validTo?: Date | null;
}

import { ApiProperty } from '@nestjs/swagger';

export class BOMListItemDTO {
  @ApiProperty({
    description: 'BOM ID',
    example: 'BOM-123',
  })
  public erpBomId: string;

  @ApiProperty({
    description: 'Material ID associated with the BOM',
    example: 'MAT-456',
  })
  public materialId: string;

  @ApiProperty({
    description: 'Valid from date and time for this BOM (ISO format)',
    example: '2025-06-01T00:00:00Z',
  })
