  })
  public validTo: string | null;
}

import { ApiProperty } from '@nestjs/swagger';
import { Type } from 'class-transformer';
import { BOMComponentResponseDTO } from '../../bom-component/dtos/bom-component-response.dto';

export class BOMResponseDTO {
  @ApiProperty({
    description: 'ERP BOM ID',
    example: 'BOM-123456',
  })
  public erpBomId: string;

  @ApiProperty({
    description: 'Valid from date and time of the BOM (ISO format)',
    example: '2025-05-01T00:00:00Z',
  })
  public validFrom: string;

  @ApiProperty({
    description:
      'Valid to date and time of the BOM (ISO format, null if valid indefinitely)',
    example: '2025-12-31T00:00:00Z',
    required: false,
    nullable: true,
  })
