import { Logger } from '@nestjs/common';
import { Repository, Raw, LessThanOrEqual } from 'typeorm';
import { BOMComponent } from '../../bom-component/bom-component.entity';
import { BOMComponentResponseDTO } from '../../bom-component/dtos/bom-component-response.dto';
import { BOM } from '../bom.entity';
import { BOMResponseDTO } from '../dtos/bom-response.dto';

/**
 * Utility functions for BOM-related operations
 */
export class BOMServiceUtility {
  private static readonly logger = new Logger(BOMServiceUtility.name);

  /**
   * Transforms a BOM component entity into a BOM component response DTO.
   * @param component - The BOM component entity to transform
   * @returns The transformed BOM component response DTO
   */
  public static transformComponentToResponseDTO(
    component: BOMComponent,
  ): BOMComponentResponseDTO {
    return {
      component: component.materialId,
      materialCategory: component.materialCategory,
      id: component.id,
      itemNumber: component.positionNr.toString().padStart(4, '0'),
      kitmat: component.kitmat || false,
      quantity: component.quantity,
      skipBomLevel: component.skipBomLevel || false,
      subComponents: [], // Empty array by default, will be filled later if needed
      uom: component.unitOfMeasure,
    } as BOMComponentResponseDTO;
  }

  /**
   * Creates standard date validity conditions for BOM queries
   * @param validAtDatetime - The date for which the BOM should be valid
   * @returns Object with typeorm conditions for validFrom and validTo fields
   */
  public static createDateValidityCondition(
    validAtDatetime: Date = new Date(),
  ): {
    validFrom: ReturnType<typeof LessThanOrEqual<Date>>;
    validTo: ReturnType<typeof Raw<Date>>;
  } {
    return {
      validFrom: LessThanOrEqual(validAtDatetime),
      validTo: Raw((column) => `COALESCE(${column}, :maxDate) > :date`, {
        maxDate: new Date('9999-12-31'),
        date: validAtDatetime,
      }),
    };
  }

  /**
   * Finds a BOM for a given material in a plant on a specific date
   * @param repository - The BOM repository
   * @param plant - The plant ID
   * @param materialId - The material ID
   * @param bomNumber - Optional specific BOM number to find
   * @param includeComponents - Whether to include component relationships
   * @param validAtDatetime - The date for which the BOM should be valid
   * @returns The BOM entity or null if not found
   */
  public static async findBOMForMaterial(
    repository: Repository<BOM>,
    plant: number,
    materialId: string,
    bomNumber: string | undefined,
    includeComponents: boolean,
    validAtDatetime: Date = new Date(),
  ): Promise<BOM | null | undefined> {
    try {
      // Build common query conditions for date validity
      const dateValidityCondition =
        this.createDateValidityCondition(validAtDatetime);

      // If a specific BOM number is provided, look for that BOM directly
      if (bomNumber) {
        return await repository.findOne({
          where: {
            plant,
            bomNumber,
            ...dateValidityCondition,
          },
          relations: includeComponents ? ['components'] : [],
        });
      }

      return undefined;
    } catch (error) {
      this.logger.error(
        `Failed to find BOM for material ${materialId} in plant ${plant}: ${error.message}`,
        error.stack,
      );
      return undefined;
    }
  }

  /**
   * Recursively builds a BOM response with nested components
   * @param bom - The BOM entity to transform
   * @param subComponentBOMs - Map of material IDs to their BOMs
   * @param processedBomNumbers - Set of already processed BOM numbers to prevent cycles
   * @param materialBomNumbersMap - Map of material IDs to their BOM numbers (may contain null values)
   * @returns The BOM response DTO with nested components
   */
  public static async buildNestedComponentsResponse(
    bom: BOM,
    subComponentBOMs: Map<string, BOM>,
    processedBomNumbers: Set<string>,
    materialBomNumbersMap: Map<string, string | null>,
  ): Promise<Array<BOMComponentResponseDTO>> {
    if (!bom.components || bom.components.length === 0) {
      return [];
    }

    // Transform all components with their already-fetched subcomponents
    const componentPromises = bom.components.map(async (component) => {
      // Transform the component itself
      const componentDto = this.transformComponentToResponseDTO(component);

      // Check if this component has its own BOM
      const bomNumber = materialBomNumbersMap.get(component.materialId);

      // If this component has its own BOM, add its subcomponents
      // Only process if the BOM number exists and hasn't been processed already (to prevent cycles)
      if (
        bomNumber &&
        !processedBomNumbers.has(bomNumber) &&
        subComponentBOMs.has(component.materialId)
      ) {
        const componentBom = subComponentBOMs.get(component.materialId);

        if (
          componentBom &&
          Array.isArray(componentBom.components) &&
          componentBom.components.length > 0
        ) {
          // Create a new set to avoid modifying the original
          const updatedProcessedBomNumbers = new Set(processedBomNumbers);
          updatedProcessedBomNumbers.add(bomNumber);

          // Recursively process subcomponents
          componentDto.subComponents = await this.buildNestedComponentsResponse(
            componentBom,
            subComponentBOMs,
            updatedProcessedBomNumbers,
            materialBomNumbersMap,
          );
        }
      }

      return componentDto;
    });

    // Wait for all components to be processed in parallel
    return Promise.all(componentPromises);
  }

  /**
   * Creates a base BOM response object from a BOM entity
   * @param bom - The BOM entity
   * @returns A BOM response DTO without components
   */
  public static createBaseBOMResponse(bom: BOM): BOMResponseDTO {
    return {
      erpBomId: bom.bomNumber,
      validFrom: bom.validFrom.toISOString(),
      validTo: bom.validTo ? bom.validTo.toISOString() : undefined,
      components: [],
    };
  }
}

