import { Injectable, InternalServerErrorException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { EntityManager, Repository } from 'typeorm';
import { BOMChangeLogCreateRequestDTO } from './dtos/bom-change-log-create-request.dto';
import { AppLogger } from '@/common/logger/app-logger';

import { BOMChangeLog } from '@/modules/bom_change_log/bom-change-log.entity';

@Injectable()
export class BOMChangeLogService {
  private readonly logger = new AppLogger(BOMChangeLogService.name);

  public constructor(
    @InjectRepository(BOMChangeLog)
    private readonly bomChangeLogRepo: Repository<BOMChangeLog>,
  ) {}

  /**
   * Creates and saves a new BOM change log entry in the database.
   *
   * This method supports both transactional and non-transactional execution.
   * If an EntityManager is provided, the change log will be created and saved using the manager (inside the current sql transaction which was opened outside current context).
   * If no manager is provided, the default repository is used (outside any explicit sql transaction).
   * @param changeLogInput - The input data containing details of the change log (e.g., plant, entity type, entity ID, operation, changed fields, source).
   * @param [manager] - (Optional) The transaction manager to use for creating and saving the change log.
   * @returns A promise that resolves to the newly created BOMChangeLog entity.
   * @throws {InternalServerErrorException} If the creation or saving process fails.
   */
  public async createChangeLog(
    changeLogInput: BOMChangeLogCreateRequestDTO,
    manager?: EntityManager,
  ): Promise<BOMChangeLog> {
    try {
      const repo = manager
        ? manager.getRepository(BOMChangeLog)
        : this.bomChangeLogRepo;
      const newChangeLog = repo.create({
        ...changeLogInput,
        changedFields: changeLogInput.changedFields
          ? JSON.stringify(changeLogInput.changedFields)
          : null,
      });
      return await repo.save(newChangeLog);
    } catch (error) {
      this.logger.error(
        `Failed to create BOM Change Log: ${error.message}`,
        error.stack,
      );
      throw new InternalServerErrorException('Failed to create BOM Change Log');
    }
  }

  /**
   * Deletes all BOM change logs matching the specified plant, entity type, and entity ID.
   *
   * This method supports both transactional and non-transactional execution.
   * If an EntityManager is provided, the deletion will be performed using the manager (inside the current sql transaction which was opened outside current context).
   * If no manager is provided, the default repository is used (outside any explicit sql transaction).
   * @param plant - The plant identifier.
   * @param entityType - The type of entity (e.g., 'bom', 'component').
   * @param entityId - The unique identifier of the entity.
   * @param [manager] - (Optional) The transaction manager to use for the deletion.
   * @returns A promise that resolves to the number of records deleted (affected rows).
   * @throws {InternalServerErrorException} If the deletion process fails.
   */
  public async deleteChangeLogsForEntity(
    plant: number,
    entityType: string,
    entityId: number,
    manager?: EntityManager,
  ): Promise<number> {
    try {
      const repo = manager
        ? manager.getRepository(BOMChangeLog)
        : this.bomChangeLogRepo;
      const deleteResult = await repo.delete({
        plant,
        entityType,
        entityId,
      });

      this.logger.log(
        `Deleted ${deleteResult.affected} BOM change logs for plant=${plant}, entityType=${entityType}, entityId=${entityId}`,
      );

      return deleteResult.affected ?? 0;
    } catch (error) {
      this.logger.error(
        `Failed to delete BOM change logs for plant=${plant}, entityType=${entityType}, entityId=${entityId}: ${error.message}`,
        error.stack,
      );
      throw new InternalServerErrorException(
        'Failed to delete BOM change logs',
      );
    }
  }
}

