import {
  ResponseWrapper,
  STATUS_CODE,
  WrappedResponse,
} from '@mesx/common-lib';
import { Injectable, BadRequestException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { BOMDefinition } from './bom-definition.entity';
import {
  BomDefinitionResponseDto,
  BomDefinitionStatus,
} from './dtos/bom-definition-response.dto';
import { BomItemPropertyDto } from './dtos/bom-item-property.dto';
import { AppLogger } from '@/common/logger/app-logger';

@Injectable()
export class BomDefinitionService {
  private static formatDateOnly(date: Date | string): string {
    if (typeof date === 'string') {
      return date.slice(0, 10);
    }

    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');

    return `${year}-${month}-${day}`;
  }

  private static getStatus(
    effectiveStartDate: Date | string,
    effectiveEndDate?: Date | string | null,
    currentDate: Date = new Date(),
  ): BomDefinitionStatus {
    const currentDateOnly = BomDefinitionService.formatDateOnly(currentDate);
    const effectiveStartDateOnly =
      BomDefinitionService.formatDateOnly(effectiveStartDate);
    const effectiveEndDateOnly = effectiveEndDate
      ? BomDefinitionService.formatDateOnly(effectiveEndDate)
      : null;

    const isActive =
      effectiveStartDateOnly <= currentDateOnly &&
      (effectiveEndDateOnly === null ||
        effectiveEndDateOnly >= currentDateOnly);

    return isActive ? 'Active' : 'Inactive';
  }

  /**
   * Applies the BOM selection priority rules to choose a single BOM from a list:
   *   1. Current BOM  – effectiveStartDate <= today AND (effectiveEndDate >= today OR null)
   *   2. Future BOM   – effectiveStartDate > today  (fallback when no current BOM exists)
   *   3. Tie-break    – when multiple BOMs satisfy a condition, the one with the
   *                     highest ID is returned (most recently created takes priority)
   *
   * Returns null when all available BOMs are purely in the past.
   * @param boms  - All BOM candidates for the given material and plant
   * @param today - Current date as a yyyy-MM-dd string
   * @returns The selected BOM, or null when all BOMs are in the past
   */
  private static selectBomByDatePriority(
    boms: Array<BOMDefinition>,
    today: string,
  ): BOMDefinition | null {
    if (boms.length === 0) {
      return null;
    }

    // ── Rule 1: Current BOMs ──────────────────────────────────────────────────
    const currentBoms = boms.filter((bom) => {
      const start = BomDefinitionService.formatDateOnly(bom.effectiveStartDate);
      const end = bom.effectiveEndDate
        ? BomDefinitionService.formatDateOnly(bom.effectiveEndDate)
        : null;

      // EffectiveStartDate <= today AND (today <= effectiveEndDate OR open-ended)
      return start <= today && (end === null || end >= today);
    });

    if (currentBoms.length > 0) {
      // Tie-break: highest ID wins
      let bestCurrent = currentBoms[0];
      for (const bom of currentBoms) {
        if (bom.id > bestCurrent.id) {
          bestCurrent = bom;
        }
      }
      return bestCurrent;
    }

    // ── Rule 2: Future BOMs (fallback) ────────────────────────────────────────
    const futureBoms = boms.filter((bom) => {
      const start = BomDefinitionService.formatDateOnly(bom.effectiveStartDate);
      return start > today;
    });

    if (futureBoms.length > 0) {
      // Tie-break: highest ID wins
      let bestFuture = futureBoms[0];
      for (const bom of futureBoms) {
        if (bom.id > bestFuture.id) {
          bestFuture = bom;
        }
      }
      return bestFuture;
    }

    // All BOMs are purely in the past – no valid selection
    return null;
  }

  /**
   * Returns true when the component material carries a procurement_type of 50
   * (phantom assembly) in any of its material-property JSON blobs.
   * Handles missing or null properties gracefully.
   * @param materialProperties - Material property records loaded from the database
   * @returns True if any property blob has procurement_type === 50
   */
  private static isPhantomMaterial(
    materialProperties:
      | Array<{ propertiesJson: Record<string, unknown> }>
      | undefined,
  ): boolean {
    if (!materialProperties || materialProperties.length === 0) {
      return false;
    }

    return materialProperties.some(
      (property) =>
        property.propertiesJson != null &&
        // Use Number() to handle both numeric 50 and string "50" from ERP
        Number(property.propertiesJson['specialProcurementType']) === 50,
    );
  }

  /**
   * Maps a BOMDefinition entity to its response DTO.
   * @param bomEntity - The selected BOMDefinition entity
   * @param requestedMaterialDefinitionId - Material definition id passed in the request
   * @param materialIdsWithChildren - Set of component material IDs that have
   *   their own BOM definitions at the same plant (drives the hasChildren flag)
   * @returns BomDefinitionResponseDto
   */
  private static mapToResponseDto(
    bomEntity: BOMDefinition,
    requestedMaterialDefinitionId: number,
    materialIdsWithChildren: Set<number>,
  ): BomDefinitionResponseDto {
    const dto = new BomDefinitionResponseDto();
    const linkedOperationDefinition = bomEntity.operationDefinitions?.find(
      (operationDefinition) =>
        operationDefinition.bomDefinitionId === bomEntity.id &&
        operationDefinition.materialDefinitionId ===
          requestedMaterialDefinitionId,
    );

    dto.id = bomEntity.id;
    dto.materialDefinitionId = bomEntity.materialDefinitionId;
    dto.plant = bomEntity.plant;
    dto.description = bomEntity.description;
    dto.useType = bomEntity.useType;
    dto.alternativeBom = bomEntity.alternativeBom;
    dto.effectiveStartDate = bomEntity.effectiveStartDate;
    dto.effectiveEndDate = bomEntity.effectiveEndDate;
    dto.erpIdentifier = bomEntity.erpIdentifier;
    dto.erpSource = bomEntity.erpSource;
    dto.operationDefinitionId = linkedOperationDefinition?.id ?? null;
    dto.operationDescription = linkedOperationDefinition?.description ?? null;
    dto.status = BomDefinitionService.getStatus(
      bomEntity.effectiveStartDate,
      bomEntity.effectiveEndDate,
    );

    // Map BOM items with phantom and hierarchy flags
    if (bomEntity.bomItems && bomEntity.bomItems.length > 0) {
      dto.bomItems = bomEntity.bomItems.map((item) => {
        const itemDto = new BomItemPropertyDto();
        itemDto.id = item.id;
        itemDto.materialDefinitionId = item.materialDefinitionId;
        itemDto.materialDefinitionCode = item.materialDefinition?.code ?? '';
        itemDto.useType = item.useType;
        itemDto.quantity = item.quantity;
        itemDto.quantityUOM = item.quantityUOM;
        itemDto.effectiveStartDate = item.effectiveStartDate;
        itemDto.effectiveEndDate = item.effectiveEndDate;
        itemDto.plant = item.plant;

        // Phantom: procurement_type === 50 in any material-property JSON blob
        itemDto.isPhantom = BomDefinitionService.isPhantomMaterial(
          item.materialDefinition?.materialProperties,
        );

        // Option 2 (lazy load): set to true when this component has its own BOM at this plant.
        // Call this endpoint again with materialDefinitionId = item.materialDefinitionId to expand.
        itemDto.hasChildren = materialIdsWithChildren.has(
          item.materialDefinitionId,
        );

        return itemDto;
      });
    }

    return dto;
  }

  private readonly logger = new AppLogger(BomDefinitionService.name);

  public constructor(
    @InjectRepository(BOMDefinition)
    private readonly bomDefinitionRepository: Repository<BOMDefinition>,
  ) {}

  /**
   * @param materialDefinitionId - ID of the parent material
   * @param plant                - Plant code
   * @returns The selected BOM with enriched items, or null if none qualifies.
   * @throws BadRequestException if parameters are invalid.
   */
  public async getBomDefinitionsByMaterialAndPlant(
    materialDefinitionId: number,
    plant: number,
  ): Promise<WrappedResponse<BomDefinitionResponseDto | undefined>> {
    try {
      const today = BomDefinitionService.formatDateOnly(new Date());

      this.logger.debug(
        `Fetching BOM definitions for materialDefinitionId=${materialDefinitionId}, plant=${plant}, today=${today}`,
      );

      // ── Step 1: Fetch all BOM candidates with full component data ─────────────
      // Fetches materialProperties via join to enable phantom detection without
      // Additional per-item queries (prevents N+1).
      const allBoms = await this.bomDefinitionRepository
        .createQueryBuilder('bd')
        .leftJoinAndSelect('bd.bomItems', 'bi')
        .leftJoinAndSelect('bi.materialDefinition', 'biMaterialDef')
        .leftJoinAndSelect('biMaterialDef.materialProperties', 'biMatProps')
        .leftJoinAndSelect(
          'bd.operationDefinitions',
          'od',
          'od.bomDefinitionId = bd.id AND od.materialDefinitionId = :materialDefinitionId',
          { materialDefinitionId },
        )
        .where('bd.materialDefinitionId = :materialDefinitionId', {
          materialDefinitionId,
        })
        .andWhere('bd.plant = :plant', { plant })
        .getMany();

      if (allBoms.length === 0) {
        this.logger.warn(
          `No BOM definitions found for materialDefinitionId=${materialDefinitionId}, plant=${plant}`,
        );
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `No BOM definitions found for materialDefinitionId=${materialDefinitionId}, plant=${plant}`,
        );
      }

      // ── Step 2: Apply selection priority rules ────────────────────────────────
      const selectedBom = BomDefinitionService.selectBomByDatePriority(
        allBoms,
        today,
      );

      if (!selectedBom) {
        this.logger.warn(
          `All BOMs are in the past for materialDefinitionId=${materialDefinitionId}, plant=${plant}`,
        );
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `All BOMs are in the past for materialDefinitionId=${materialDefinitionId}, plant=${plant}`,
        );
      }

      this.logger.debug(
        `Selected BOM id=${selectedBom.id} for materialDefinitionId=${materialDefinitionId}, plant=${plant}`,
      );

      // ── Step 3: Batch-check which component materials have sub-BOMs ───────────
      // A single IN-query avoids one DB hit per item (prevents N+1 for hasChildren).
      const componentMaterialIds = [
        ...new Set(
          (selectedBom.bomItems ?? []).map((item) => item.materialDefinitionId),
        ),
      ];

      const materialIdsWithChildren = new Set<number>();

      if (componentMaterialIds.length > 0) {
        const childRows = await this.bomDefinitionRepository
          .createQueryBuilder('bd')
          .select('bd.materialDefinitionId', 'materialDefinitionId')
          .where('bd.materialDefinitionId IN (:...ids)', {
            ids: componentMaterialIds,
          })
          .andWhere('bd.plant = :plant', { plant })
          .groupBy('bd.materialDefinitionId')
          .getRawMany<{ materialDefinitionId: number }>();

        for (const row of childRows) {
          materialIdsWithChildren.add(Number(row.materialDefinitionId));
        }
      }

      // ── Step 4: Map entity → DTO with phantom and hierarchy flags ─────────────
      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'BOM definitions retrieved successfully',
        BomDefinitionService.mapToResponseDto(
          selectedBom,
          materialDefinitionId,
          materialIdsWithChildren,
        ),
      );
    } catch (error) {
      if (error instanceof BadRequestException) {
        return ResponseWrapper.error(STATUS_CODE.BAD_REQUEST, error.message);
      }

      this.logger.error(
        `Error fetching BOM definitions for materialDefinitionId=${materialDefinitionId}, plant=${plant}`,
        error instanceof Error ? error.message : String(error),
      );
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Unexpected server error',
