  Entity,
  JoinColumn,
  ManyToOne,
  PrimaryGeneratedColumn,
} from 'typeorm';
import { BOMDefinition } from '../bom-definition/bom-definition.entity';
import { TimeStamp } from '@/modules/generics/timestamp';
import { MaterialDefinition } from '@/modules/isa95-material-model/material/internal/material-definition.entity';

@Entity({ name: 'bom_items', schema: 'isa95' })
export class BOMItems extends TimeStamp {
  @Column({ name: 'plant', type: 'smallint' })
  public plant: number;

  @PrimaryGeneratedColumn({ name: 'id' })
  public id: number;

  @Column({ name: 'bom_definition_id', nullable: false, type: 'int' })
  public bomDefinitionId: number;

  @Column({ name: 'material_definition_id', nullable: false, type: 'int' })
  public materialDefinitionId: number;

  @Column({ length: 8, name: 'use_type', nullable: false, type: 'char' })
  public useType: string;

  @Column({
    name: 'quantity',
    nullable: true,
    precision: 13,
    scale: 3,
    type: 'numeric',
  })
  public quantity?: number | null;

  @Column({ length: 3, name: 'quantity_uom', nullable: true, type: 'char' })
  public quantityUOM?: string | null;

  @Column({ name: 'effective_start_date', nullable: false, type: 'date' })
  public effectiveStartDate: Date;

  @Column({ name: 'effective_end_date', nullable: true, type: 'date' })
  public effectiveEndDate?: Date | null;

  @ManyToOne(() => BOMDefinition, (bomDefinition) => bomDefinition.bomItems, {
    nullable: false,
  })
  @JoinColumn([
    {
      name: 'bom_definition_id',
      referencedColumnName: 'id',
      foreignKeyConstraintName: 'fk_bom_items_bom_definition',
    },
  ])
  public bomDefinition: BOMDefinition;

  @ManyToOne(
    () => MaterialDefinition,
    (materialDefinition) => materialDefinition.bomItems,
    { nullable: false },
  )
  @JoinColumn([
    {
      name: 'material_definition_id',
      referencedColumnName: 'id',
      foreignKeyConstraintName: 'fk_bom_items_material_definition',
    },
  ])
  public materialDefinition: MaterialDefinition;
}

