const getOperationStatus = (
  effectiveStartDate: Date | null,
  effectiveEndDate: Date | null,
  referenceDate: Date,
): 'Active' | 'Inactive' => {
  const currentDate = new Date(referenceDate);

  // Start date check
  const isStarted =
    !effectiveStartDate || new Date(effectiveStartDate) <= currentDate;

  // End date check
  const isNotEnded =
    !effectiveEndDate || new Date(effectiveEndDate) >= currentDate;

  return isStarted && isNotEnded ? 'Active' : 'Inactive';
};

@Injectable()
export class OperationDefinitionService {
  private readonly logger = new AppLogger(OperationDefinitionService.name);

  public constructor(
    @InjectRepository(OperationDefinition)
    private readonly operationDefinitionRepository: Repository<OperationDefinition>,

    @InjectRepository(MaterialDefinition)
    private readonly materialRepo: Repository<MaterialDefinition>,
  ) {}

  /**
   * Retrieves a distinct list of material codes for dropdown filtering.
   *
   * Business rules:
   * - Always filtered by plant.
   * - If equipment is provided, only materials associated with that equipment
   * in operation definitions are returned.
   * - Results are returned as distinct material codes, sorted alphabetically.
   * @param plant - Plant context (mandatory)
   * @param search - Optional search term (minimum 3 characters).
   * @param equipment - Optional equipment code used to filter materials
   * @returns Promise resolving to a list of distinct material codes
   */
  public async getDistinctMaterials(
    plant: number,
    search?: string,
    equipment?: string,
  ): Promise<WrappedResponse<Array<DistinctMaterialCodeDto> | undefined>> {
    try {
      const qb = this.materialRepo
        .createQueryBuilder('m')
        .distinct(true)
        .innerJoin('m.operationDefinitions', 'od', 'od.plant = :plant', {
          plant,
        })
        .select('m.code', 'code')
        .where('m.plant = :plant', { plant })
        .andWhere('m.code LIKE :search', { search: `${search}%` });

      if (equipment) {
        qb.andWhere('od.equipment = :equipment', { equipment });
      }

      const rows = await qb
        .orderBy('m.code', 'ASC')
        .take(20)
        .getRawMany<DistinctMaterialCodeDto>();

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Distinct materials retrieved successfully',
        rows,
      );
    } catch (error: unknown) {
      this.logger.error(
        `Failed to fetch distinct materials for plant ${plant}`,
        error instanceof Error ? error.stack : String(error),
      );
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Unexpected server error',
      );
    }
  }

  /**
   * Retrieves a distinct list of equipment codes for dropdown filtering.
   *
   * Business rules:
   * - Always filtered by plant.
   * - If material code is provided, only equipment associated with that material
   * in operation definitions is returned.
   * - Results are returned as distinct equipment codes, sorted alphabetically.
   * @param plant - Plant context (mandatory)
   * @param materialCode - Optional material code used to filter equipment
   * @returns Promise resolving to a list of distinct equipment codes
   */
  public async getDistinctEquipment(
    plant: number,
    materialCode?: string,
  ): Promise<WrappedResponse<Array<DistinctEquipmentDto> | undefined>> {
    try {
      const qb = this.operationDefinitionRepository
        .createQueryBuilder('od')
        .distinct(true)
        .select('od.equipment', 'equipment')
        .where('od.plant = :plant', { plant });

      if (materialCode) {
        qb.innerJoin('od.materialDefinition', 'm', 'm.code = :materialCode', {
          materialCode,
        });
      }

      const rows = await qb
        .orderBy('od.equipment', 'ASC')
        .getRawMany<DistinctEquipmentDto>();

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Distinct equipment retrieved successfully',
        rows,
      );
    } catch (error: unknown) {
      this.logger.error(
        `Failed to fetch distinct equipment for plant ${plant} and material ${materialCode}`,
        error instanceof Error ? error.stack : String(error),
      );
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Unexpected server error',
      );
    }
  }

  /**
   * Retrieves operation definitions for table display.
   * Supports optional filtering by material and/or equipment.
   * @param parameters - Filtering and pagination parameters
   * @returns A promise resolving to a list of operation definition table rows
   */
  public async getOperationDefinitions(
    parameters: GetOperationDefinitionsDto,
  ): Promise<WrappedResponse<PaginatedOperationDefinitionsResult | undefined>> {
    const {
      plant,
      material,
      equipment,
      limit: rawLimit = 10,
      page: rawPage = 1,
      status = 'All',
    } = parameters;
    const limit = Math.max(1, Math.trunc(Number(rawLimit) || 10));
    const page = Math.max(1, Math.trunc(Number(rawPage) || 1));
    const offset = (page - 1) * limit;
    const today = new Date();

    try {
      const qb = this.operationDefinitionRepository
        .createQueryBuilder('od')
        .innerJoin('od.materialDefinition', 'm')
        .leftJoin(
          BOMDefinition,
          'bd',
          'bd.id = od.bomDefinitionId AND bd.plant = od.plant',
        )
        .where('od.plant = :plant', { plant });

      if (material) {
        qb.andWhere('m.code = :material', { material });
      }

      if (equipment) {
        qb.andWhere('od.equipment = :equipment', { equipment });
      }

      if (status === 'Active') {
        qb.andWhere('od.effectiveStartDate <= :today', { today }).andWhere(
          'od.effectiveEndDate >= :today',
          { today },
        );
      } else if (status === 'Inactive') {
        qb.andWhere(
          new Brackets((dateFilter) => {
            dateFilter
              .where('od.effectiveStartDate > :today', { today })
              .orWhere('od.effectiveEndDate < :today', { today });
          }),
        );
      }

      const total = await qb.clone().getCount();

      const rows = await qb
        .select([
          'od.plant AS plant',
          'od.id AS operationId',
          'od.bomDefinitionId AS bomDefinitionId',
          'od.materialDefinitionId AS materialDefinitionId',
          'm.code AS material',
          'od.version AS version',
          'od.equipment AS equipment',
          'od.effectiveStartDate AS effectiveStartDate',
          'od.effectiveEndDate AS effectiveEndDate',
          'bd.erpIdentifier AS operationBillId',
        ])
        .orderBy('m.code', 'ASC')
        .addOrderBy('od.version', 'ASC')
        .offset(offset)
        .limit(limit)
        .getRawMany<OperationDefinitionTableRowDto>();

      const mappedRows = rows.map((row) => ({
        ...row,
        status: getOperationStatus(
          row.effectiveStartDate,
          row.effectiveEndDate,
          today,
        ),
      }));

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Operation definitions retrieved successfully',
        { rows: mappedRows, total, limit, page },
      );
    } catch (error: unknown) {
      this.logger.error(
        `Failed to fetch operation definitions for plant ${plant}`,
        error instanceof Error ? error.stack : String(error),
      );
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Unexpected server error',
      );
    }
  }

  /**
   * Retrieves full read-only details of an operation definition.
   * This endpoint is used to populate the operation definition details drawer.
   *
   * Business rule:
   * - Operation Bill ID corresponds to the ERP Identifier of the BOM Definition.
   * @param operationId - Unique identifier of the operation definition
   * @returns A promise resolving to the operation definition details
   */
  public async getOperationDefinitionDetails(
    operationId: number,
  ): Promise<WrappedResponse<OperationDefinitionDetailsDto | undefined>> {
    try {
      const operationDefinitionDetails =
        await this.operationDefinitionRepository
          .createQueryBuilder('od')
          .innerJoin('od.materialDefinition', 'm')
          .leftJoin(BOMDefinition, 'bd', 'bd.id = od.bomDefinitionId')
          .select([
            'od.id AS operationId',
            'm.code AS material',
            'od.version AS version',
            'od.description AS description',
            'od.equipment AS equipment',
            'od.effectiveStartDate AS effectiveStartDate',
            'od.effectiveEndDate AS effectiveEndDate',
            'RTRIM(bd.erpIdentifier) AS operationBillId',
            'od.taskGroupId AS taskGroupId',
            'od.groupCounter AS groupCounter',
          ])
          .where('od.id = :operationId', { operationId })
          .getRawOne<OperationDefinitionDetailsDto>();

      if (!operationDefinitionDetails) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Operation definition with id ${operationId} does not exist`,
        );
      }

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Operation definition retrieved successfully',
        operationDefinitionDetails,
      );
    } catch (error: unknown) {
      this.logger.error(
        `Failed to fetch operation definition details for operationId ${operationId}`,
        error instanceof Error ? error.stack : String(error),
      );
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Unexpected server error',
      );
    }
  }
}

