  @Column({ length: 40, name: 'description', nullable: true, type: 'nvarchar' })
  public description?: string | null;

  @Column({
    name: 'hmac_duration',
    nullable: true,
    precision: 5,
    scale: 3,
    type: 'numeric',
  })
  public hmacDuration?: number | null;

  @Column({
    name: 'hmod_duration',
    nullable: true,
    precision: 5,
    scale: 3,
    type: 'numeric',
  })
  public hmodDuration?: number | null;

  @Column({
    name: 'hlog_duration',
    nullable: true,
    precision: 5,
    scale: 3,
    type: 'numeric',
  })
  public hlogDuration?: number | null;

  @Column({ length: 3, name: 'duration_uom', nullable: true, type: 'char' })
  public durationUOM?: string | null;

  @Column({
    default: 'Production',
    length: 11,
    name: 'operation_type',
    nullable: false,
    type: 'nvarchar',
  })
  public operationType: string;

  @Column({ name: 'effective_start_date', nullable: false, type: 'date' })
  public effectiveStartDate: Date;

  @Column({ name: 'effective_end_date', nullable: false, type: 'date' })
  public effectiveEndDate: Date;

  @Column({ length: 4, name: 'erp_identifier', nullable: false, type: 'char' })
  public erpIdentifier: string;

  @Column({ length: 8, name: 'equipment', nullable: false, type: 'char' })
  public equipment: string;

  @Column({
    name: 'prod_time',
    nullable: true,
    precision: 5,
    scale: 3,
    type: 'numeric',
  })
  public prodTime?: number | null;

  /**
   * SAP LOIROU E1MAPLL.MATNR — persisted to allow direct segment queries
   * without joining back through operation_definition → material_definition.
   */
  @Column({
    length: 18,
    name: 'material_code',
    nullable: false,
    type: 'varchar',
  })
  public materialCode?: string | null;

  /**
   * SAP LOIROU E1MAPLL.PLNNR — persisted to allow direct segment queries
   * and to trace which routing task group produced this segment.
   * Matches operation_definition.task_group_id at ingestion time.
