import {
  ResponseWrapper,
  STATUS_CODE,
  WrappedResponse,
} from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Brackets, Repository, SelectQueryBuilder } from 'typeorm';
import { GetOperationSegmentsByMaterialDto } from './dtos/get-operation-segments-by-material.dto';
import { GetOperationSegmentsDto } from './dtos/get-operation-segments.dto';
import { GroupedOperationSegmentsResultDto } from './dtos/grouped-operation-segments-result.dto';
import { OperationSegmentDetailsDto } from './dtos/operation-segment-details.dto';
import { OperationSegmentTableRowDto } from './dtos/operation-segment-table-row.dto';
import { OperationSegment } from './operation-segment.entity';
import { AppLogger } from '@/common/logger/app-logger';

const getOperationStatus = (
  effectiveStartDate: Date | null,
  effectiveEndDate: Date | null,
  referenceDate: Date,
): 'Active' | 'Inactive' => {
  const currentDate = new Date(referenceDate);
  const currentDateTimestamp = new Date(currentDate).setHours(0, 0, 0, 0);
  const isStarted =
    effectiveStartDate &&
    new Date(effectiveStartDate).setHours(0, 0, 0, 0) <= currentDateTimestamp;

  const isNotEnded =
    effectiveEndDate &&
    new Date(effectiveEndDate).setHours(0, 0, 0, 0) >= currentDateTimestamp;

  return isStarted && isNotEnded ? 'Active' : 'Inactive';
};

@Injectable()
export class OperationSegmentService {
  private static applyStatusFilter(
    queryBuilder: SelectQueryBuilder<OperationSegment>,
    status: 'All' | 'Active' | 'Inactive',
    today: Date,
    effectiveDateAlias: 'od' | 'os',
  ): void {
    if (status === 'Active') {
      queryBuilder
        .andWhere(`${effectiveDateAlias}.effectiveStartDate <= :today`, {
          today,
        })
        .andWhere(`${effectiveDateAlias}.effectiveEndDate >= :today`, {
          today,
        });
      return;
    }

    if (status === 'Inactive') {
      queryBuilder.andWhere(
        new Brackets((dateFilter) => {
          dateFilter
            .where(`${effectiveDateAlias}.effectiveStartDate > :today`, {
              today,
            })
            .orWhere(`${effectiveDateAlias}.effectiveEndDate < :today`, {
              today,
            });
        }),
      );
    }
  }

  private static async getOperationSegmentRows(
    queryBuilder: SelectQueryBuilder<OperationSegment>,
  ): Promise<Array<OperationSegmentTableRowDto>> {
    return queryBuilder
      .select([
        'os.plant AS plant',
        'os.id AS id',
        'os.operationDefinitionId AS operationDefinitionId',
        'os.materialCode AS materialCode',
        'os.groupCounter AS groupCounter',
        'os.taskGroupId AS taskGroupId',
        'os.effectiveStartDate AS effectiveStartDate',
        'os.effectiveEndDate AS effectiveEndDate',
        'os.erpIdentifier AS operationNumber',
        'os.equipment AS equipment',
        'os.description AS description',
        'os.hmacDuration AS hmacDuration',
        'os.hmodDuration AS hmodDuration',
        'os.hlogDuration AS hlogDuration',
        'os.durationUOM AS durationUom',
      ])
      .orderBy('os.materialCode', 'ASC')
      .addOrderBy('os.groupCounter', 'ASC')
      .addOrderBy('os.taskGroupId', 'ASC')
      .addOrderBy('os.effectiveStartDate', 'ASC')
      .addOrderBy('os.erpIdentifier', 'ASC')
      .getRawMany<OperationSegmentTableRowDto>();
  }

  private static groupOperationSegmentRows(
    rows: Array<OperationSegmentTableRowDto>,
    referenceDate: Date,
  ): Array<GroupedOperationSegmentsResultDto> {
    const rowsWithStatus = rows.map((row) => ({
      ...row,
      status: getOperationStatus(
        row.effectiveStartDate,
        row.effectiveEndDate,
        referenceDate,
      ),
    }));

    const groupedRowsMap = new Map<string, GroupedOperationSegmentsResultDto>();

    for (const row of rowsWithStatus) {
      const groupKey = [
        row.materialCode ?? '',
        row.groupCounter ?? '',
        row.taskGroupId ?? '',
        row.effectiveStartDate
          ? new Date(row.effectiveStartDate).toISOString()
          : '',
      ].join('||');

      if (groupedRowsMap.has(groupKey)) {
        groupedRowsMap.get(groupKey)?.rows.push(row);
      } else {
        groupedRowsMap.set(groupKey, {
          effectiveStartDate: row.effectiveStartDate,
          groupCounter: row.groupCounter,
          materialCode: row.materialCode,
          rows: [row],
          taskGroupId: row.taskGroupId,
        });
      }
    }

    return [...groupedRowsMap.values()];
  }

  private readonly logger = new AppLogger(OperationSegmentService.name);

  public constructor(
    @InjectRepository(OperationSegment)
    private readonly operationSegmentRepository: Repository<OperationSegment>,
  ) {}

  /**
   * Retrieves operation segments for a given operation definition.
   *
   * Business rules:
   * - Always filtered by plant.
   * - Operation definition identifier is mandatory.
   * @param parameters - Plant and operation definition context
   * @returns A promise resolving to a list of operation segment table rows
   */
  public async getOperationSegments(
    parameters: GetOperationSegmentsDto,
  ): Promise<
    WrappedResponse<Array<GroupedOperationSegmentsResultDto> | undefined>
  > {
    const { plant, operationDefinitionId, status = 'All' } = parameters;
    const today = new Date();

    try {
      const qb = this.operationSegmentRepository
        .createQueryBuilder('os')
        .innerJoin('os.operationDefinition', 'od')
        .where('os.plant = :plant', { plant })
        .andWhere('od.id = :operationDefinitionId', { operationDefinitionId });

      OperationSegmentService.applyStatusFilter(qb, status, today, 'od');

      const rows = await OperationSegmentService.getOperationSegmentRows(qb);

      if (rows.length === 0) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `No operation segments found for operationDefinitionId ${operationDefinitionId}`,
        );
      }

      const groupedRows = OperationSegmentService.groupOperationSegmentRows(
        rows,
        today,
      );

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Operation segments retrieved successfully',
        groupedRows,
      );
    } catch (error: unknown) {
      this.logger.error(
        `Failed to fetch operation segments for operationDefinitionId ${operationDefinitionId}`,
        error instanceof Error ? error.stack : String(error),
      );
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Unexpected server error',
      );
    }
  }

  /**
   * Retrieves operation segments associated with a selected material.
   * Business rules:
   * - Always filtered by plant.
   * - Material is mandatory.
   * - Used to populate Operation Segments table when a material is selected.
   * @param parameters - Plant and material context
   * @returns A promise resolving to paginated operation segment rows
   */
  public async getOperationSegmentsByMaterial(
    parameters: GetOperationSegmentsByMaterialDto,
  ): Promise<
    WrappedResponse<Array<GroupedOperationSegmentsResultDto> | undefined>
  > {
    const { plant, material, status = 'All' } = parameters;
    const normalizedMaterial = material.trim();
    const today = new Date();

    try {
      const qb = this.operationSegmentRepository
        .createQueryBuilder('os')
        .where('os.plant = :plant', { plant })
        .andWhere('os.materialCode = :material', {
          material: normalizedMaterial,
        });

      OperationSegmentService.applyStatusFilter(qb, status, today, 'os');

      const rows = await OperationSegmentService.getOperationSegmentRows(qb);

      if (rows.length === 0) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `No operation segments found for material ${normalizedMaterial}`,
        );
      }

      const groupedRows = OperationSegmentService.groupOperationSegmentRows(
        rows,
        today,
      );

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Operation segments retrieved successfully',
        groupedRows,
      );
    } catch (error: unknown) {
      this.logger.error(
        `Failed to fetch operation segments by material ${normalizedMaterial}`,
        error instanceof Error ? error.stack : String(error),
      );
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Unexpected server error',
      );
    }
  }

  /**
   * Retrieves full read-only details of an operation segment.
   *
   * Business rules:
   * - Operation number corresponds to ERP Identifier.
   * - Used to populate the Operation Segment details drawer.
   * @param operationNumber - ERP Identifier of the operation segment
   * @returns A promise resolving to the operation segment details
   */
  public async getOperationSegmentDetails(
    operationNumber: string,
  ): Promise<WrappedResponse<OperationSegmentDetailsDto | undefined>> {
    try {
      const operationSegmentDetails = await this.operationSegmentRepository
        .createQueryBuilder('os')
        .select([
          'os.operationDefinitionId AS operationDefinitionId',
          'os.materialCode AS materialCode',
          'os.groupCounter AS groupCounter',
          'os.taskGroupId AS taskGroupId',
          'os.effectiveStartDate AS effectiveStartDate',
          'os.effectiveEndDate AS effectiveEndDate',
          'os.erpIdentifier AS operationNumber',
          'os.equipment AS equipment',
          'os.description AS description',
          'os.hmacDuration AS hmacDuration',
          'os.hmodDuration AS hmodDuration',
          'os.hlogDuration AS hlogDuration',
          'os.durationUOM AS durationUom',
        ])
        .where('os.erpIdentifier = :operationNumber', { operationNumber })
        .getRawOne<OperationSegmentDetailsDto>();

      if (!operationSegmentDetails) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Operation segment with ERP identifier ${operationNumber} does not exist`,
        );
      }

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Operation segment retrieved successfully',
        operationSegmentDetails,
      );
    } catch (error: unknown) {
      this.logger.error(
        `Failed to fetch operation segment details for operationNumber ${operationNumber}`,
        error instanceof Error ? error.stack : String(error),
      );
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Unexpected server error',
      );
    }
  }
}

