    materialClassId: number,
    isUsedByMaterials = false,
  ): MaterialClassPropertiesResponseDto {
    const normalizedLanguageCode = normalizeLanguageCode(languageCode);
    const dto = new MaterialClassPropertiesResponseDto();

    if (properties.length === 0) {
      dto.languageCode = normalizedLanguageCode;
      dto.materialClassCode = '';
      dto.materialClassDescription = '';
      dto.materialClassId = materialClassId;
      dto.properties = [];

      return dto;
    }

    const { materialClass } = properties[0];
    const matchedDescription = findPreferredDescription(
      materialClass.descriptions,
      normalizedLanguageCode,
    );

    dto.languageCode = resolveDescriptionLanguageCode(
      matchedDescription,
      normalizedLanguageCode,
    );
    dto.materialClassCode = materialClass.code;
    dto.materialClassDescription = matchedDescription?.description ?? '';
    dto.materialClassId = materialClass.id;
    dto.properties = properties.map((property) =>
      MaterialClassPropertyItemResponseDto.fromEntity(
        property,
        normalizedLanguageCode,
        isUsedByMaterials,
      ),
    );

    return dto;
  }

