interface MaterialClassPropertySemanticsJson extends Record<string, unknown> {
  cardinality?: MaterialClassPropertyCardinality;
  classPropertyType?: MaterialClassPropertyType;
  class_property_type?: MaterialClassPropertyType;
  allowedValues?: Array<string>;
