};

export class MaterialClassPropertyItemResponseDto {
  public static createPropertySemanticsJson(input: {
    cardinality?: MaterialClassPropertyCardinality;
    classPropertyType?: MaterialClassPropertyType;
    allowedValues?: Array<string> | null;
    clearAllowedValues?: boolean;
    defaultValue?: string;
    clearDefaultValue?: boolean;
    propertySemanticsJson?: Record<string, unknown>;
  }): Record<string, unknown> {
    const nextPropertySemanticsJson = toPropertySemanticsJson(
      input.propertySemanticsJson,
    );

    nextPropertySemanticsJson.cardinality =
      input.cardinality ?? nextPropertySemanticsJson.cardinality ?? 'single';
    const nextClassPropertyType =
      input.classPropertyType ??
      nextPropertySemanticsJson.classPropertyType ??
      nextPropertySemanticsJson.class_property_type ??
      'InstanceType';
    nextPropertySemanticsJson.classPropertyType = nextClassPropertyType;
    nextPropertySemanticsJson.class_property_type = nextClassPropertyType;

    if (input.clearDefaultValue) {
      delete nextPropertySemanticsJson.defaultValue;
      delete nextPropertySemanticsJson.default_value;
    } else if (input.defaultValue !== undefined) {
      nextPropertySemanticsJson.defaultValue = input.defaultValue;
      delete nextPropertySemanticsJson.default_value;
    }

    if (input.clearAllowedValues) {
      delete nextPropertySemanticsJson.allowedValues;
    } else if (
      input.allowedValues !== undefined &&
      input.allowedValues !== null
    ) {
      nextPropertySemanticsJson.allowedValues = input.allowedValues;
    }

    return nextPropertySemanticsJson;
  }

