    const dto = new MaterialClassPropertyItemResponseDto();
    const classPropertyType =
      propertySemanticsJson.classPropertyType ??
      propertySemanticsJson.class_property_type;
    let defaultValue: string | undefined;

    if (typeof propertySemanticsJson.defaultValue === 'string') {
      defaultValue = propertySemanticsJson.defaultValue;
    } else if (typeof propertySemanticsJson.default_value === 'string') {
      defaultValue = propertySemanticsJson.default_value;
    }

    if (classPropertyType !== undefined) {
      propertySemanticsJson.classPropertyType = classPropertyType;
    }

    if (defaultValue !== undefined) {
      propertySemanticsJson.defaultValue = defaultValue;
    }

    dto.code = property.code;
    dto.allowedValues = Array.isArray(propertySemanticsJson.allowedValues)
      ? propertySemanticsJson.allowedValues.filter(
          (allowedValue): allowedValue is string =>
            typeof allowedValue === 'string',
        )
      : undefined;
    dto.defaultValue = defaultValue;
    dto.description = matchedPropertyDescription?.description ?? '';
    dto.externalMapping = property.externalMapping ?? undefined;
    dto.id = property.id;
    dto.isCustom = property.isCustom;
    dto.isUsedByMaterials = isUsedByMaterials;
    dto.length = property.length ?? undefined;
    dto.parentMaterialClassPropertyId =
