import {
  ResponseWrapper,
  STATUS_CODE,
  WrappedResponse,
} from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { CreateMaterialMaterialClassDto } from '../dtos/create-material-material-class.dto';
import { UpdateMaterialMaterialClassDto } from '../dtos/update-material-material-class.dto';
import { MaterialMaterialClass } from './material-material-class.entity';

@Injectable()
export class MaterialMaterialClassService {
  public constructor(
    @InjectRepository(MaterialMaterialClass)
    private readonly materialMaterialClassRepository: Repository<MaterialMaterialClass>,
  ) {}

  public async create(
    payload: CreateMaterialMaterialClassDto,
  ): Promise<WrappedResponse<MaterialMaterialClass | undefined>> {
    try {
      const materialDefinition =
        await this.materialMaterialClassRepository.manager
          .getRepository('MaterialDefinition')
          .findOne({ where: { id: payload.materialDefinitionId } });

      const materialClass = await this.materialMaterialClassRepository.manager
        .getRepository('MaterialClass')
        .findOne({ where: { id: payload.materialClassId } });

      if (!materialDefinition || !materialClass) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          'MaterialDefinition or MaterialClass does not exist',
        );
      }

      const materialMaterialClass = this.materialMaterialClassRepository.create(
        {
          materialDefinition,
          materialClass,
        },
      );

      return ResponseWrapper.success(
        STATUS_CODE.CREATED,
        'Material material class created successfully',
        await this.materialMaterialClassRepository.save(materialMaterialClass),
      );
    } catch {
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Unexpected server error',
      );
    }
  }

  public async findAll(): Promise<
    WrappedResponse<Array<MaterialMaterialClass> | undefined>
  > {
    try {
      const items = await this.materialMaterialClassRepository.find();

      if (items.length === 0) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          'Material material classes do not exist',
        );
      }

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Material material classes retrieved successfully',
        items,
      );
    } catch {
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Unexpected server error',
      );
    }
  }

  public async findOne(
    id: number,
  ): Promise<WrappedResponse<MaterialMaterialClass | undefined>> {
    try {
      const materialMaterialClass =
        await this.materialMaterialClassRepository.findOne({ where: { id } });
      if (!materialMaterialClass) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Material material class with id ${id} does not exist`,
        );
      }

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Material material class retrieved successfully',
        materialMaterialClass,
      );
    } catch {
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Unexpected server error',
      );
    }
  }

  public async update(
    id: number,
    payload: UpdateMaterialMaterialClassDto,
  ): Promise<WrappedResponse<MaterialMaterialClass | undefined>> {
    try {
      const existing = await this.materialMaterialClassRepository.findOne({
        where: { id },
      });

      if (!existing) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Material material class with id ${id} does not exist`,
        );
      }

      await this.materialMaterialClassRepository.update(id, payload);
      return await this.findOne(id);
    } catch {
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Unexpected server error',
      );
    }
  }

  public async remove(id: number): Promise<WrappedResponse<undefined>> {
    try {
      const result = await this.materialMaterialClassRepository.delete(id);

      if (!result.affected) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Material material class with id ${id} does not exist`,
        );
      }

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Material material class deleted successfully',
      );
    } catch {
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Unexpected server error',
      );
    }
  }
}

import {
  ResponseWrapper,
  STATUS_CODE,
  WrappedResponse,
} from '@mesx/common-lib';
import {
  BadRequestException,
  ConflictException,
  Injectable,
  Logger,
  NotFoundException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { EntityManager, Repository } from 'typeorm';
import { MaterialPropertyDescription } from '../material/internal/material-property-description.entity';
import { MaterialProperty } from '../material/internal/material-property.entity';
import { PropertyDataType } from '../shared/internal/property-data-type.entity';
import { CreateMaterialClassPropertyDto } from './dtos/create-material-class-property.dto';
import { MaterialClassPropertiesResponseDto } from './dtos/material-class-properties-response.dto';
import { MaterialClassPropertyItemResponseDto } from './dtos/material-class-property-item-response.dto';
import { UpdateMaterialClassPropertyDto } from './dtos/update-material-class-property.dto';
import { MaterialClassProperty } from './internal/material-class-property.entity';
import { MaterialClass } from './internal/material-class.entity';
import { MaterialMaterialClass } from './internal/material-material-class.entity';

@Injectable()
export class MaterialClassPropertyService {
  private static buildUsedByMaterialsDeleteMessage(code: string): string {
    return `Material class property ${code} cannot be deleted because its class is used by one or more materials`;
  }

  private static normalizeLanguageCode(languageCode?: string): string {
    return (languageCode?.trim() || 'EN').toUpperCase();
  }

  private static normalizeOptionalTrimmedValue(
    value: string | null | undefined,
  ): string | undefined {
    if (value == null) {
      return undefined;
    }

    const normalizedValue = value.trim();
    return normalizedValue === '' ? undefined : normalizedValue;
  }

  private static normalizeAllowedValues(
    allowedValues: Array<string> | null | undefined,
  ): Array<string> | null | undefined {
    if (allowedValues === undefined || allowedValues === null) {
      return allowedValues;
    }

    return allowedValues.map((allowedValue) => allowedValue.trim());
  }

  private static ensureMaterialClassIdMatchesRoute(
    routeMaterialClassId: number,
    payloadMaterialClassId: number,
  ): void {
    if (routeMaterialClassId !== payloadMaterialClassId) {
      throw new BadRequestException(
        `materialClassId in payload (${payloadMaterialClassId}) must match route id (${routeMaterialClassId})`,
      );
    }
  }

  public static ensureOnlyDescriptionCanChangeWhenUsed(
    materialClassProperty: MaterialClassProperty,
    payload: UpdateMaterialClassPropertyDto,
    isUsedByMaterials: boolean,
  ): void {
    if (!materialClassProperty.isCustom || !isUsedByMaterials) {
      return;
    }

    const lockedFields: Array<keyof UpdateMaterialClassPropertyDto> = [
      'cardinality',
      'allowedValues',
      'classPropertyType',
      'code',
      'defaultValue',
      'length',
      'propertyDataTypeId',
    ];

    const changedLockedField = lockedFields.find(
      (field) => payload[field] !== undefined,
    );

    if (changedLockedField !== undefined) {
      throw new ConflictException(
        `Material class property ${materialClassProperty.code} is used by one or more materials. Only the description can be updated.`,
      );
    }
  }

  private readonly logger = new Logger(MaterialClassPropertyService.name);

  public constructor(
    @InjectRepository(MaterialClass)
    private readonly materialClassRepository: Repository<MaterialClass>,
    @InjectRepository(MaterialClassProperty)
    private readonly materialClassPropertyRepository: Repository<MaterialClassProperty>,
    @InjectRepository(MaterialPropertyDescription)
    private readonly materialPropertyDescriptionRepository: Repository<MaterialPropertyDescription>,
    @InjectRepository(MaterialProperty)
    private readonly materialPropertyRepository: Repository<MaterialProperty>,
    @InjectRepository(PropertyDataType)
    private readonly propertyDataTypeRepository: Repository<PropertyDataType>,
  ) {}

  private async ensurePropertyDataTypeExists(
    propertyDataTypeId: number,
  ): Promise<void> {
    const propertyDataType = await this.propertyDataTypeRepository.findOne({
      where: { id: propertyDataTypeId },
    });

    if (!propertyDataType) {
      throw new NotFoundException(
        `Property data type with id ${propertyDataTypeId} does not exist`,
      );
    }
  }

  private async ensureMaterialClassExists(
    materialClassId: number,
  ): Promise<void> {
    const materialClass = await this.materialClassRepository.findOne({
      where: { id: materialClassId },
    });

    if (!materialClass) {
      throw new NotFoundException(
        `Material class with id ${materialClassId} not found`,
      );
    }
  }

  private async ensureUniquePropertyCode(
    materialClassId: number,
    code: string,
    excludedPropertyId?: number,
  ): Promise<void> {
    const conflictingProperty =
      await this.materialClassPropertyRepository.findOne({
        where: {
          code,
          materialClassId,
        },
      });

    if (conflictingProperty && conflictingProperty.id !== excludedPropertyId) {
      throw new ConflictException(
        `Material class property with code ${code} already exists for material class id ${materialClassId}`,
      );
    }
  }

  private async upsertDescription(
    materialClassPropertyId: number,
    description: string,
    languageCode = 'EN',
    descriptionRepository: Repository<MaterialPropertyDescription> = this
      .materialPropertyDescriptionRepository,
  ): Promise<void> {
    const code =
      MaterialClassPropertyService.normalizeLanguageCode(languageCode);
    const existingDescription = await descriptionRepository.findOne({
      where: {
        code,
        materialClassPropertyId,
      },
    });

    if (existingDescription) {
      existingDescription.description = description;
      await descriptionRepository.save(existingDescription);
      return;
    }

    const nextDescription = descriptionRepository.create({
      code,
      description,
      materialClassPropertyId,
    });
    await descriptionRepository.save(nextDescription);
  }

  public async findOneEntity(
    id: number,
    materialClassId?: number,
    withRelations = true,
  ): Promise<MaterialClassProperty> {
    const materialClassProperty =
      await this.materialClassPropertyRepository.findOne({
        relations: withRelations ? ['descriptions', 'propertyDataType'] : [],
        where: materialClassId === undefined ? { id } : { id, materialClassId },
      });

    if (!materialClassProperty) {
      throw new NotFoundException(
        materialClassId === undefined
          ? `Material class property with id ${id} not found`
          : `Material class property with id ${id} not found for material class id ${materialClassId}`,
      );
    }

    return materialClassProperty;
  }

  private async isMaterialClassUsedByMaterials(
    materialClassId: number,
  ): Promise<boolean> {
    const linkedMaterial = await this.materialPropertyRepository.manager
      .getRepository(MaterialMaterialClass)
      .createQueryBuilder('materialMaterialClass')
      .select('1')
      .where('materialMaterialClass.materialClassId = :materialClassId', {
        materialClassId,
      })
      .limit(1)
      .getRawOne();

    if (linkedMaterial !== null && linkedMaterial !== undefined) {
      return true;
    }
    return false;
  }

  public async isPropertyUsedByMaterials(
    materialClassId: number,
    propertyCode: string,
  ): Promise<boolean> {
    const materialAssignmentCount =
      await this.materialPropertyRepository.manager.count(
        MaterialMaterialClass,
        { where: { materialClassId } },
      );

    if (materialAssignmentCount > 0) {
      return true;
    }

    const materialProperties = await this.materialPropertyRepository.find({
      select: ['propertiesJson'],
      where: { materialClassId },
    });

    return materialProperties.some((materialProperty) =>
      Object.prototype.hasOwnProperty.call(
        materialProperty.propertiesJson ?? {},
        propertyCode,
      ),
    );
  }

  public async findOne(
    id: number,
    languageCode?: string,
    materialClassId?: number,
  ): Promise<MaterialClassPropertyItemResponseDto> {
    const property = await this.findOneEntity(id, materialClassId);
    const isUsedByMaterials = await this.isMaterialClassUsedByMaterials(
      property.materialClassId,
    );

    return MaterialClassPropertyItemResponseDto.fromEntity(
      property,
      languageCode,
      isUsedByMaterials,
    );
  }

  public async findByMaterialClassId(
    materialClassId: number,
    languageCode?: string,
  ): Promise<WrappedResponse<MaterialClassPropertiesResponseDto | undefined>> {
    try {
      await this.ensureMaterialClassExists(materialClassId);

      const properties = await this.materialClassPropertyRepository.find({
        order: { code: 'ASC', id: 'ASC' },
        relations: [
          'descriptions',
          'materialClass',
          'materialClass.descriptions',
          'propertyDataType',
        ],
        where: { materialClassId },
      });

      if (properties.length === 0) {
        throw new NotFoundException(
          `Material class properties not found for material class id ${materialClassId}`,
        );
      }

      const isUsedByMaterials =
        await this.isMaterialClassUsedByMaterials(materialClassId);

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Material class properties retrieved successfully',
        MaterialClassPropertiesResponseDto.fromEntities(
          properties,
          languageCode,
          materialClassId,
          isUsedByMaterials,
        ),
      );
    } catch (error) {
      if (error instanceof NotFoundException) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          error.message.replace('not found', 'does not exist'),
        );
      }

      if (error instanceof BadRequestException) {
        return ResponseWrapper.error(STATUS_CODE.BAD_REQUEST, error.message);
      }

      if (error instanceof ConflictException) {
        return ResponseWrapper.error(STATUS_CODE.CONFLICT, error.message);
      }

      this.logger.error(
        'Error retrieving material class properties',
        error instanceof Error ? error.stack : undefined,
      );

      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Unexpected server error',
      );
    }
  }

  public async create(
    materialClassId: number,
    payload: CreateMaterialClassPropertyDto,
  ): Promise<
    WrappedResponse<MaterialClassPropertyItemResponseDto | undefined>
  > {
    try {
      MaterialClassPropertyService.ensureMaterialClassIdMatchesRoute(
        materialClassId,
        payload.materialClassId,
      );
      await this.ensureMaterialClassExists(materialClassId);

      const normalizedCode = payload.code.trim();

      if (!normalizedCode) {
        throw new BadRequestException(
          'Material class property code must not be empty',
        );
      }

      await this.ensureUniquePropertyCode(materialClassId, normalizedCode);
      await this.ensurePropertyDataTypeExists(payload.propertyDataTypeId);

      const normalizedLanguageCode =
        MaterialClassPropertyService.normalizeLanguageCode(
          payload.languageCode,
        );
      const normalizedDescription = payload.description?.trim();
      const normalizedDefaultValue =
        MaterialClassPropertyService.normalizeOptionalTrimmedValue(
          payload.defaultValue ?? undefined,
        );
      const normalizedAllowedValues =
        MaterialClassPropertyService.normalizeAllowedValues(
          payload.allowedValues,
        );

      const createdProperty =
        await this.materialClassPropertyRepository.manager.transaction(
          async (manager: EntityManager) => {
            const propertySemanticsJson =
              MaterialClassPropertyItemResponseDto.createPropertySemanticsJson({
                cardinality: payload.cardinality,
                allowedValues:
                  normalizedAllowedValues === null
                    ? undefined
                    : normalizedAllowedValues,
                classPropertyType: payload.classPropertyType,
                defaultValue: normalizedDefaultValue,
              });

            const nextMaterialClassProperty = manager.create(
              MaterialClassProperty,
              {
                code: normalizedCode,
                isCustom: true,
                length: payload.length ?? null,
                materialClassId,
                propertyDataTypeId: payload.propertyDataTypeId,
                propertySemanticsJson,
              },
            );

            const savedProperty = await manager.save(
              MaterialClassProperty,
              nextMaterialClassProperty,
            );

            if (normalizedDescription) {
              await this.upsertDescription(
                savedProperty.id,
                normalizedDescription,
                normalizedLanguageCode,
                manager.getRepository(MaterialPropertyDescription),
              );
            }

            return savedProperty;
          },
        );

      return ResponseWrapper.success(
        STATUS_CODE.CREATED,
        'Material class property created successfully',
        await this.findOne(
          createdProperty.id,
          normalizedLanguageCode,
          materialClassId,
        ),
      );
    } catch (error) {
      if (error instanceof NotFoundException) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          error.message.replace('not found', 'does not exist'),
        );
      }

      if (error instanceof BadRequestException) {
        return ResponseWrapper.error(STATUS_CODE.BAD_REQUEST, error.message);
      }

      if (error instanceof ConflictException) {
        return ResponseWrapper.error(STATUS_CODE.CONFLICT, error.message);
      }

      this.logger.error(
        'Error creating material class property',
        error instanceof Error ? error.stack : undefined,
      );

      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Unexpected server error',
      );
    }
  }

  public async update(
    materialClassId: number,
    id: number,
    payload: UpdateMaterialClassPropertyDto,
  ): Promise<
    WrappedResponse<MaterialClassPropertyItemResponseDto | undefined>
  > {
    try {
      MaterialClassPropertyService.ensureMaterialClassIdMatchesRoute(
        materialClassId,
        payload.materialClassId,
      );
      await this.ensureMaterialClassExists(materialClassId);
      const normalizedLanguageCode =
        MaterialClassPropertyService.normalizeLanguageCode(
          payload.languageCode,
        );
      const materialClassProperty = await this.findOneEntity(
        id,
        materialClassId,
        false,
      );

      if (payload.code !== undefined) {
        const normalizedCode = payload.code.trim();

        if (!normalizedCode) {
          throw new BadRequestException(
            'Material class property code must not be empty',
          );
        }

        await this.ensureUniquePropertyCode(
          materialClassId,
          normalizedCode,
          id,
        );

        materialClassProperty.code = normalizedCode;
      }

      let normalizedDescription: string | undefined;
      if (payload.description !== undefined) {
        normalizedDescription = payload.description.trim();

        if (!normalizedDescription) {
          throw new BadRequestException(
            'Material class property description must not be empty',
          );
        }
      }

      if (payload.propertyDataTypeId !== undefined) {
        await this.ensurePropertyDataTypeExists(payload.propertyDataTypeId);
        materialClassProperty.propertyDataTypeId = payload.propertyDataTypeId;
      }

      if (payload.length !== undefined) {
        materialClassProperty.length = payload.length;
      }

      let normalizedDefaultValue: string | undefined;
      let clearDefaultValue = false;
      if (payload.defaultValue !== undefined) {
        normalizedDefaultValue =
          MaterialClassPropertyService.normalizeOptionalTrimmedValue(
            payload.defaultValue ?? undefined,
          );

        if (
          payload.defaultValue === null ||
          normalizedDefaultValue === undefined
        ) {
          clearDefaultValue = true;
        }
      }

      const normalizedAllowedValues =
        MaterialClassPropertyService.normalizeAllowedValues(
          payload.allowedValues,
        );

      materialClassProperty.propertySemanticsJson =
        MaterialClassPropertyItemResponseDto.createPropertySemanticsJson({
          allowedValues:
            normalizedAllowedValues === null
              ? undefined
              : normalizedAllowedValues,
          cardinality: payload.cardinality,
          classPropertyType: payload.classPropertyType,
          clearAllowedValues: normalizedAllowedValues === null,

          clearDefaultValue,
          defaultValue: normalizedDefaultValue,
          propertySemanticsJson: materialClassProperty.propertySemanticsJson,
        });
      await this.materialClassPropertyRepository.manager.transaction(
        async (manager: EntityManager) => {
          await manager.save(MaterialClassProperty, materialClassProperty);

          if (normalizedDescription !== undefined) {
            await this.upsertDescription(
              materialClassProperty.id,
              normalizedDescription,
              normalizedLanguageCode,
              manager.getRepository(MaterialPropertyDescription),
            );
          }
        },
      );

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Material class property updated successfully',
        await this.findOne(id, normalizedLanguageCode, materialClassId),
      );
    } catch (error) {
      if (error instanceof NotFoundException) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          error.message.replace('not found', 'does not exist'),
        );
      }

      if (error instanceof BadRequestException) {
        return ResponseWrapper.error(STATUS_CODE.BAD_REQUEST, error.message);
      }

      if (error instanceof ConflictException) {
        return ResponseWrapper.error(STATUS_CODE.CONFLICT, error.message);
      }

      this.logger.error(
        'Error updating material class property',
        error instanceof Error ? error.stack : undefined,
      );

      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Unexpected server error',
      );
    }
  }

  public async remove(
    materialClassId: number,
    id: number,
  ): Promise<WrappedResponse<undefined>> {
    try {
      const materialClassProperty = await this.findOneEntity(
        id,
        materialClassId,
      );

      if (await this.isMaterialClassUsedByMaterials(materialClassId)) {
        throw new ConflictException(
          MaterialClassPropertyService.buildUsedByMaterialsDeleteMessage(
            materialClassProperty.code,
          ),
        );
      }

      await this.materialClassPropertyRepository.manager.transaction(
        async (manager: EntityManager) => {
          await manager.getRepository(MaterialPropertyDescription).delete({
            materialClassPropertyId: id,
          });

          await manager
            .getRepository(MaterialClassProperty)
            .update(
              { parentMaterialClassPropertyId: id },
              { parentMaterialClassPropertyId: null },
            );

          const deleteResult = await manager
            .getRepository(MaterialClassProperty)
            .delete({
              id,
              materialClassId,
            });

          if (!deleteResult.affected) {
            throw new NotFoundException(
              `Material class property with id ${id} not found for material class id ${materialClassId}`,
            );
          }
        },
      );

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Material class property deleted successfully',
      );
    } catch (error) {
      if (error instanceof NotFoundException) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          error.message.replace('not found', 'does not exist'),
        );
      }

      if (error instanceof BadRequestException) {
        return ResponseWrapper.error(STATUS_CODE.BAD_REQUEST, error.message);
      }

      if (error instanceof ConflictException) {
        return ResponseWrapper.error(STATUS_CODE.CONFLICT, error.message);
      }

      this.logger.error(
        'Error deleting material class property',
        error instanceof Error ? error.stack : undefined,
      );

      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Unexpected server error',
      );
    }
  }
}

