import { MaterialClassRelatedMaterialPropertyDto } from './dtos/material-class-related-material-property.dto';
import { MaterialClassRelatedMaterialDto } from './dtos/material-class-related-material.dto';
import { MaterialClassResponseDto } from './dtos/material-class-response.dto';
import { UpdateMaterialClassDto } from './dtos/update-material-class.dto';
import { MaterialClassDescription } from './internal/material-class-description.entity';
import { MaterialClassInheritance } from './internal/material-class-inheritance.entity';
import { MaterialClassProperty } from './internal/material-class-property.entity';
import { MaterialClass } from './internal/material-class.entity';
import { MaterialMaterialClass } from './internal/material-material-class.entity';
import { AppLogger } from '@/common/logger/app-logger';

@Injectable()
export class MaterialClassService {
  private static buildNotCustomDeleteMessage(code: string): string {
    return `Material class ${code} cannot be deleted because it is not custom`;
  }

  private static buildUsedByMaterialsDeleteMessage(code: string): string {
    return `Material class ${code} cannot be deleted because it is used by one or more materials`;
  }

  private static selectMaterialDescription(
    descriptions:
      | Array<{
          code?: string;
          description: string;
        }>
      | undefined,
    language: string,
  ):
    | {
        code?: string;
        description: string;
      }
    | undefined {
    return findPreferredDescription(descriptions, language);
  }

  private static mapMaterialForClass(
    materialDefinition: MaterialDefinition,
    materialClassId: number,
    language: string,
  ): MaterialClassRelatedMaterialDto {
    const selectedDescription = MaterialClassService.selectMaterialDescription(
      materialDefinition.materialDescriptionByLanguages,
      language,
    );

    const properties = (materialDefinition.materialProperties ?? [])
      .filter((property) => property.materialClassId === materialClassId)
      .sort((left, right) => left.id - right.id)
      .map<MaterialClassRelatedMaterialPropertyDto>((property) => ({
        id: property.id,
        materialClassId: property.materialClassId,
        propertiesJson: property.propertiesJson ?? {},
      }));

    return {
      code: materialDefinition.code?.trim() ?? '',
      description: selectedDescription?.description ?? null,
      descriptionLanguageCode: selectedDescription?.code?.trim().toUpperCase()
        ? selectedDescription.code.trim().toUpperCase()
        : null,
      id: materialDefinition.id,
      plant: materialDefinition.plant,
      properties,
    };
  }

  private static toResponseDto(
    materialClass: MaterialClass,
    languageCode = 'EN',
    isUsedByMaterials = false,
    materialClassPropertiesCount = materialClass.materialClassProperties
      ?.length ?? 0,
    descriptions = materialClass.descriptions,
  ): MaterialClassResponseDto {
    const matchedDescription = findPreferredDescription(
      descriptions,
      languageCode,
    );

    return {
      code: materialClass.code,
      description: matchedDescription?.description ?? '',
      id: materialClass.id,
      isCustom: materialClass.isCustom,
      isUsedByMaterials,
      languageCode: resolveDescriptionLanguageCode(
        matchedDescription,
        languageCode,
      ),
      materialClassPropertiesCount,
    };
  }

  private static mapFindAllRawRows(
    rows: Array<{
      id: number | string;
      code: string;
      isCustom: boolean | number | string;
      descriptionId: number | string | null;
      descriptionCode: string | null;
      description: string | null;
      propertyCount: number | string;
      isUsed: number | string;
    }>,
  ): Array<MaterialClassResponseDto> {
    const materialClassMap = new Map<
      number,
      {
        code: string;
        descriptions: Array<MaterialClassDescription>;
        isCustom: boolean;
        isUsed: boolean;
        propertyCount: number;
      }
    >();

    for (const row of rows) {
      const id = Number(row.id);

      if (!materialClassMap.has(id)) {
        materialClassMap.set(id, {
          code: row.code,
          descriptions: [],
          isCustom:
            row.isCustom === true || row.isCustom === 1 || row.isCustom === '1',
          isUsed: row.isUsed === 1 || row.isUsed === '1',
          propertyCount: Number(row.propertyCount),
        });
      }

      if (
        row.descriptionId !== null &&
        row.descriptionId !== undefined &&
        row.descriptionCode !== null &&
        row.description !== null
      ) {
        const desc = new MaterialClassDescription();
        desc.id = Number(row.descriptionId);
        desc.code = row.descriptionCode;
        desc.description = row.description;
        desc.materialClassId = id;

        const mappedMaterialClass = materialClassMap.get(id);
        if (mappedMaterialClass !== undefined) {
          mappedMaterialClass.descriptions.push(desc);
        }
      }
    }

    return [...materialClassMap.entries()].map(([id, entry]) => {
      const materialClass = new MaterialClass();
      materialClass.id = id;
      materialClass.code = entry.code;
      materialClass.isCustom = entry.isCustom;

      return MaterialClassService.toResponseDto(
        materialClass,
        'EN',
        entry.isUsed,
        entry.propertyCount,
        entry.descriptions,
      );
    });
  }

  private readonly logger = new AppLogger(MaterialClassService.name);

  public constructor(
    @InjectRepository(MaterialClass)
    private readonly materialClassRepository: Repository<MaterialClass>,
    @InjectRepository(MaterialClassDescription)
    private readonly materialClassDescriptionRepository: Repository<MaterialClassDescription>,
    private readonly dataSource: DataSource,
  ) {}

  private async findUsedMaterialClassIds(
    materialClassIds: Array<number>,
  ): Promise<Set<number>> {
    if (materialClassIds.length === 0) {
      return new Set<number>();
    }

    const assignmentRows = await this.dataSource
      .getRepository(MaterialMaterialClass)
      .createQueryBuilder('materialMaterialClass')
      .select('materialMaterialClass.materialClassId', 'materialClassId')
      .where(
        'materialMaterialClass.materialClassId IN (:...materialClassIds)',
        {
          materialClassIds,
        },
      )
      .groupBy('materialMaterialClass.materialClassId')
      .getRawMany<{ materialClassId: number | string }>();

    const propertyRows = await this.dataSource
      .getRepository(MaterialProperty)
      .createQueryBuilder('materialProperty')
      .select('materialProperty.materialClassId', 'materialClassId')
      .where('materialProperty.materialClassId IN (:...materialClassIds)', {
        materialClassIds,
      })
      .groupBy('materialProperty.materialClassId')
      .getRawMany<{ materialClassId: number | string }>();

    return new Set(
      [...assignmentRows, ...propertyRows].map((row) =>
        Number(row.materialClassId),
      ),
    );
  }

  private async isMaterialClassUsedByMaterials(
    materialClassId: number,
  ): Promise<boolean> {
    const usedMaterialClassIds = await this.findUsedMaterialClassIds([
      materialClassId,
    ]);

    return usedMaterialClassIds.has(materialClassId);
  }

  public async create(
    payload: CreateMaterialClassDto,
  ): Promise<WrappedResponse<MaterialClassResponseDto | undefined>> {
    try {
      const normalizedCode = payload.code.trim();
      const normalizedLanguageCode = normalizeLanguageCode(
        payload.languageCode,
      );
      const normalizedDescription = payload.description.trim();

      const existingMaterialClass = await this.materialClassRepository.findOne({
        where: { code: normalizedCode },
      });

      if (existingMaterialClass) {
        return ResponseWrapper.error(
          STATUS_CODE.CONFLICT,
          `Material class with code ${normalizedCode} already exists`,
        );
      }

      const materialClass = await this.dataSource.transaction(
        async (manager) => {
          const createdMaterialClass = await manager.save(
            MaterialClass,
            manager.create(MaterialClass, {
              code: normalizedCode,
              isCustom: payload.isCustom ?? false,
            }),
          );

          await manager.save(
            MaterialClassDescription,
            manager.create(MaterialClassDescription, {
              code: normalizedLanguageCode,
              description: normalizedDescription,
              materialClassId: createdMaterialClass.id,
            }),
          );

          return manager.findOneOrFail(MaterialClass, {
            where: { id: createdMaterialClass.id },
            relations: ['descriptions', 'materialClassProperties'],
          });
        },
      );

      return ResponseWrapper.success(
        STATUS_CODE.CREATED,
        'Material class created successfully',
        MaterialClassService.toResponseDto(
          materialClass,
          normalizedLanguageCode,
        ) ?? undefined,
      );
    } catch (error) {
      if (error instanceof ConflictException) {
        return ResponseWrapper.error(STATUS_CODE.CONFLICT, error.message);
      }

      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Unexpected server error',
      );
    }
  }

  public async findAll(): Promise<
    WrappedResponse<Array<MaterialClassResponseDto> | undefined>
  > {
    try {
      const queryBuilder =
        this.materialClassRepository.createQueryBuilder('mc');

      const assignedToMaterialSubQuery = queryBuilder
        .subQuery()
        .select('1')
        .from(MaterialMaterialClass, 'mmc')
        .where('mmc.materialClassId = mc.id')
        .getQuery();

      const usedByPropertySubQuery = queryBuilder
        .subQuery()
        .select('1')
        .from(MaterialProperty, 'mp')
        .where('mp.materialClassId = mc.id')
        .getQuery();

      const rows = await queryBuilder
        .select('mc.id', 'id')
        .addSelect('mc.code', 'code')
        .addSelect('mc.isCustom', 'isCustom')
        .addSelect('mcd.id', 'descriptionId')
        .addSelect('mcd.code', 'descriptionCode')
        .addSelect('mcd.description', 'description')
        .addSelect(
          (qb) =>
            qb
              .select('COUNT(1)')
              .from(MaterialClassProperty, 'mcp')
              .where('mcp.materialClassId = mc.id'),
          'propertyCount',
        )
        .addSelect(
          `CASE WHEN EXISTS ${assignedToMaterialSubQuery} OR EXISTS ${usedByPropertySubQuery} THEN 1 ELSE 0 END`,
          'isUsed',
        )
        .leftJoin('mc.descriptions', 'mcd')
        .orderBy('mc.code', 'ASC')
        .addOrderBy('mcd.code', 'ASC')
        .getRawMany<{
          id: number | string;
          code: string;
          isCustom: boolean | number | string;
          descriptionId: number | string | null;
          descriptionCode: string | null;
          description: string | null;
          propertyCount: number | string;
          isUsed: number | string;
        }>();

      if (rows.length === 0) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          'Material classes do not exist',
        );
      }

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Material classes retrieved successfully',
        MaterialClassService.mapFindAllRawRows(rows) ?? undefined,
      );
    } catch (error) {
      this.logger.error(
        'Error retrieving material classes',
        error instanceof Error ? error.stack : undefined,
      );
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Unexpected server error',
      );
    }
  }

  public async findRelatedMaterials(
    materialClassId: number,
    language?: string,
  ): Promise<
    WrappedResponse<Array<MaterialClassRelatedMaterialDto> | undefined>
  > {
    try {
      const materialClass = await this.materialClassRepository.findOne({
        where: { id: materialClassId },
      });

      if (!materialClass) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Material class with id ${materialClassId} does not exist`,
        );
      }

      const selectedLanguage = normalizeLanguageCode(
        language ?? defaultDescriptionLanguageCode,
      );

      const links = await this.dataSource
        .getRepository(MaterialMaterialClass)
        .find({
          where: { materialClassId },
          order: {
            materialDefinitionId: 'ASC',
          },
          relations: [
            'materialDefinition',
            'materialDefinition.materialDescriptionByLanguages',
            'materialDefinition.materialProperties',
          ],
        });

      const seenMaterialIds = new Set<number>();

      const materials = links
        .map((link) => link.materialDefinition)
        .filter(Boolean)
        .filter((materialDefinition) => {
          if (seenMaterialIds.has(materialDefinition.id)) {
            return false;
          }

          seenMaterialIds.add(materialDefinition.id);
          return true;
        })
        .map((materialDefinition) =>
          MaterialClassService.mapMaterialForClass(
            materialDefinition,
            materialClassId,
            selectedLanguage,
          ),
        );

      if (materials.length === 0) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Related materials for material class with id ${materialClassId} do not exist`,
        );
      }

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Related materials retrieved successfully',
        materials ?? undefined,
      );
    } catch {
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Unexpected server error',
      );
    }
  }

  public async findOne(
    id: number,
  ): Promise<WrappedResponse<MaterialClassResponseDto | undefined>> {
    try {
      const materialClass = await this.materialClassRepository.findOne({
        relations: ['descriptions', 'materialClassProperties'],
        where: { id },
      });
      if (!materialClass) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Material class with id ${id} does not exist`,
        );
      }
      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Material class retrieved successfully',
        MaterialClassService.toResponseDto(
          materialClass,
          'EN',
          await this.isMaterialClassUsedByMaterials(id),
        ) ?? undefined,
      );
    } catch {
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Unexpected server error',
      );
    }
  }

  public async update(
    id: number,
    payload: UpdateMaterialClassDto,
  ): Promise<WrappedResponse<MaterialClassResponseDto | undefined>> {
    try {
      const existingMaterialClass = await this.materialClassRepository.findOne({
        relations: ['descriptions', 'materialClassProperties'],
        where: { id },
      });

      if (!existingMaterialClass) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Material class with id ${id} does not exist`,
        );
      }

      const nextCode = payload.code?.trim();
      const nextDescription = payload.description?.trim();
      const normalizedLanguageCode = normalizeLanguageCode(
        payload.languageCode,
      );

      if (nextCode && nextCode !== existingMaterialClass.code) {
        const codeConflict = await this.materialClassRepository.findOne({
          where: { code: nextCode },
        });

        if (codeConflict && codeConflict.id !== id) {
          return ResponseWrapper.error(
            STATUS_CODE.CONFLICT,
            `Material class with code ${nextCode} already exists`,
          );
        }
      }

      const materialClass = await this.dataSource.transaction(
        async (manager) => {
          existingMaterialClass.code = nextCode ?? existingMaterialClass.code;
          existingMaterialClass.isCustom =
            payload.isCustom ?? existingMaterialClass.isCustom;

          await manager.save(MaterialClass, existingMaterialClass);

          if (nextDescription) {
            const existingDescription =
              await this.materialClassDescriptionRepository.findOne({
                where: {
                  code: normalizedLanguageCode,
                  materialClassId: existingMaterialClass.id,
                },
              });

            if (existingDescription) {
              existingDescription.description = nextDescription;
              await manager.save(MaterialClassDescription, existingDescription);
            } else {
              await manager.save(
                MaterialClassDescription,
                manager.create(MaterialClassDescription, {
                  code: normalizedLanguageCode,
                  description: nextDescription,
                  materialClassId: existingMaterialClass.id,
                }),
              );
            }
          }

          return manager.findOneOrFail(MaterialClass, {
            where: { id: existingMaterialClass.id },
            relations: ['descriptions', 'materialClassProperties'],
          });
        },
      );

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Material class updated successfully',
        MaterialClassService.toResponseDto(
          materialClass,
          normalizedLanguageCode,
          await this.isMaterialClassUsedByMaterials(id),
        ),
      );
    } catch (error) {
      if (error instanceof ConflictException) {
        return ResponseWrapper.error(STATUS_CODE.CONFLICT, error.message);
      }

      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Unexpected server error',
      );
    }
  }

  public async remove(id: number): Promise<WrappedResponse<undefined>> {
    try {
      await this.dataSource.transaction(async (manager) => {
        const existingMaterialClass = await manager.findOne(MaterialClass, {
          where: { id },
        });

        if (!existingMaterialClass) {
          throw new NotFoundException(`Material class with id ${id} not found`);
        }

        if (!existingMaterialClass.isCustom) {
          throw new ConflictException(
            MaterialClassService.buildNotCustomDeleteMessage(
              existingMaterialClass.code,
            ),
          );
        }

        if (await this.isMaterialClassUsedByMaterials(id)) {
          throw new ConflictException(
            MaterialClassService.buildUsedByMaterialsDeleteMessage(
              existingMaterialClass.code,
            ),
          );
        }

        const materialClassProperties = await manager
          .getRepository(MaterialClassProperty)
          .find({
            select: ['id'],
            where: { materialClassId: id },
          });
        const materialClassPropertyIds = materialClassProperties.map(
          (property) => property.id,
        );

        if (materialClassPropertyIds.length > 0) {
          await manager.update(
            MaterialClassProperty,
            {
              parentMaterialClassPropertyId: In(materialClassPropertyIds),
            },
            {
              parentMaterialClassPropertyId: null,
            },
          );

          await manager.delete(MaterialPropertyDescription, {
            materialClassPropertyId: In(materialClassPropertyIds),
          });
        }

        await manager.delete(MaterialProperty, { materialClassId: id });
        await manager.delete(MaterialMaterialClass, { materialClassId: id });
        await manager
          .createQueryBuilder()
          .delete()
          .from(MaterialClassInheritance)
          .where('parent_material_class_id = :id', { id })
          .orWhere('child_material_class_id = :id', { id })
          .execute();
        await manager.delete(MaterialClassDescription, { materialClassId: id });
        await manager.delete(MaterialClassProperty, { materialClassId: id });

        const result = await manager.delete(MaterialClass, id);
        if (!result.affected) {
          throw new NotFoundException(`Material class with id ${id} not found`);
        }
      });

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Material class deleted successfully',
      );
    } catch (error) {
      if (error instanceof NotFoundException) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Material class with id ${id} does not exist`,
        );
      }

      if (error instanceof ConflictException) {
        return ResponseWrapper.error(STATUS_CODE.CONFLICT, error.message);
      }

      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Unexpected server error',
      );
    }
  }

  public async assignRelatedMaterial(
    materialClassId: number,
    materialDefinitionId: number,
  ): Promise<WrappedResponse<MaterialClassRelatedMaterialDto | undefined>> {
    try {
      const materialClass = await this.materialClassRepository.findOne({
        where: { id: materialClassId },
      });

      if (!materialClass) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Material class with id ${materialClassId} does not exist`,
        );
      }

      const materialDefinition = await this.dataSource
        .getRepository(MaterialDefinition)
        .findOne({ where: { id: materialDefinitionId } });

      if (!materialDefinition) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Material definition with id ${materialDefinitionId} does not exist`,
        );
      }

      const { plant } = materialDefinition;

      const existing = await this.dataSource
        .getRepository(MaterialMaterialClass)
        .findOne({ where: { materialClassId, materialDefinitionId, plant } });

      if (!existing) {
        await this.dataSource.getRepository(MaterialMaterialClass).save(
          this.dataSource.getRepository(MaterialMaterialClass).create({
            materialClassId,
            materialDefinitionId,
            plant,
          }),
        );
      }

      const selectedLanguage = defaultDescriptionLanguageCode;

      const updated = await this.dataSource
        .getRepository(MaterialDefinition)
        .findOne({
          where: { id: materialDefinitionId },
          relations: ['materialDescriptionByLanguages', 'materialProperties'],
        });

      if (!updated) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Material definition with id ${materialDefinitionId} does not exist`,
        );
      }

      return ResponseWrapper.success(
        STATUS_CODE.CREATED,
        'Related material assigned successfully',
        MaterialClassService.mapMaterialForClass(
          updated,
          materialClassId,
          selectedLanguage,
        ),
      );
    } catch (error) {
      if (error instanceof NotFoundException) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          error.message.replace('not found', 'does not exist'),
        );
      }

      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Unexpected server error',
      );
    }
  }

  public async removeRelatedMaterial(
    materialClassId: number,
    materialDefinitionId: number,
    plant: number,
  ): Promise<WrappedResponse<undefined>> {
    try {
      const result = await this.dataSource
        .getRepository(MaterialMaterialClass)
        .delete({ materialClassId, materialDefinitionId, plant });

      if (!result.affected) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Relation between material class ${materialClassId} and material definition ${materialDefinitionId} for plant ${plant} does not exist`,
        );
      }

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Related material removed successfully',
      );
    } catch {
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Unexpected server error',
      );
    }
  }
}

import { ApiProperty, ApiPropertyOptional } from '@nestjs/swagger';
import { Type } from 'class-transformer';
import {
  ArrayUnique,
  IsArray,
  IsInt,
  IsOptional,
  Max,
  Min,
  ValidateNested,
} from 'class-validator';
import { MAX_SQL_INT } from '../../shared/dtos/integer-range.constants';
import { MaterialDefinitionPropertyInputDto } from './material-definition-property-input.dto';

export class AssignMaterialClassDto {
  @ApiProperty({
    description:
      'Full list of material class ids that should remain linked to the material',
    example: [2, 3, 4],
    maximum: MAX_SQL_INT,
    minimum: 1,
    type: [Number],
  })
  @IsArray()
  @ArrayUnique()
  @Type(() => Number)
  @IsInt({ each: true })
  @Min(1, { each: true })
  @Max(MAX_SQL_INT, { each: true })
  public materialClassIds: Array<number>;

  @ApiPropertyOptional({
    description:
      'Optional property values keyed by material class. Submitted values are merged into the existing material properties for the same class.',
    type: MaterialDefinitionPropertyInputDto,
    isArray: true,
  })
  @IsOptional()
  @IsArray()
  @ValidateNested({ each: true })
  @Type(() => MaterialDefinitionPropertyInputDto)
  public properties?: Array<MaterialDefinitionPropertyInputDto>;
}

