import { ApiProperty, ApiPropertyOptional } from '@nestjs/swagger';
import { Transform, Type } from 'class-transformer';
import {
  ArrayMaxSize,
  ArrayMinSize,
  IsArray,
  IsInt,
  IsOptional,
  IsString,
  Max,
  MaxLength,
  Min,
} from 'class-validator';
import { MAX_SQL_INT } from '../../shared/dtos/integer-range.constants';

export class GetMaterialDefinitionsQueryDto {
  @ApiProperty({
    description: 'Plant identifier',
    example: 1000,
    maximum: MAX_SQL_INT,
    minimum: 1,
    type: Number,
  })
  @Type(() => Number)
  @IsInt()
  @Min(1000)
  @Max(9999)
  public plant!: number;

  @ApiPropertyOptional({
    default: 'EN',
    description: 'Language code used to resolve descriptions',
    example: 'EN',
    maxLength: 2,
    minLength: 2,
    type: String,
  })
  @IsOptional()
  @IsString()
  @MaxLength(2)
  public languageCode = 'EN';

  @ApiPropertyOptional({
    description: 'Material class codes used to filter material properties',
    example: ['generalMaterialIdentification', 'inventoryProperty'],
    type: [String],
  })
  @IsOptional()
  @Transform(({ value }) => {
    if (Array.isArray(value)) {
      return value;
    }

    if (typeof value === 'string') {
      return value
        .split(',')
        .map((item) => item.trim())
        .filter((item) => item !== '');
    }

    return value;
  })
  @IsArray()
  @ArrayMinSize(1)
  @ArrayMaxSize(100)
  @IsString({ each: true })
  public materialPropertyClassCodes!: Array<string>;

  @ApiPropertyOptional({
    default: 1,
    description: 'Page number',
