import { MaterialDefinitionListItemRawResponseDto } from '../dtos/material-definition-list-item-raw-response.dto';
import { MaterialDefinitionPropertyDto } from '../dtos/material-definition-property.dto';
import {
  MaterialClassRawDto,
  MaterialDefinitionRawResponseDto,
  MaterialPropertyRawDto,
} from '../dtos/material-definition-raw-response.dto';
import { MaterialDefinitionResponseDto } from '../dtos/material-definition-response.dto';

interface DescriptionByLanguageLike {
  code?: string;
  description: string;
}

export class MaterialDefinitionMapper {
  public static toResponseDtoFromListItem(
    materialDefinition: MaterialDefinitionListItemRawResponseDto,
    languageCode = 'EN',
  ): MaterialDefinitionResponseDto {
    const descriptionByLanguage =
      typeof materialDefinition.description === 'string' &&
      materialDefinition.description.trim() !== ''
        ? materialDefinition.description
        : undefined;

    const materialDescriptionByLanguages =
      descriptionByLanguage === undefined
        ? []
        : [{ code: 'EN', description: descriptionByLanguage }];

    return this.toResponseDto(
      {
        code: materialDefinition.code,
        createdAt: materialDefinition.createdAt,
        erpSource: materialDefinition.erpSource,
        id: materialDefinition.id,
        materialDescriptionByLanguages,
        materialMaterialClasses: this.parseJsonArray(
          materialDefinition.materialMaterialClasses,
        ),
        materialProperties: this.parseJsonArray(
          materialDefinition.materialProperties,
        ),
        plant: materialDefinition.plant,
        updatedAt: materialDefinition.updatedAt,
      },
      languageCode,
    );
  }

  public static toResponseDto(
    materialDefinition: MaterialDefinitionRawResponseDto,
    languageCode = 'EN',
  ): MaterialDefinitionResponseDto {
    const materialClassById = new Map<number, MaterialClassRawDto>(
      (materialDefinition.materialMaterialClasses ?? []).map(
        (materialMaterialClass) => [
          materialMaterialClass.materialClass.id,
          materialMaterialClass.materialClass,
        ],
      ),
    );

    const materialClasses: Array<MaterialDefinitionClassDto> = (
      materialDefinition.materialMaterialClasses ?? []
    ).map((materialMaterialClass) => ({
      code: materialMaterialClass.materialClass.code,
      description: this.findDescriptionByLanguage(
        materialMaterialClass.materialClass.descriptions,
        languageCode,
      ),
      id: materialMaterialClass.materialClass.id,
    }));

    const properties: Array<MaterialDefinitionPropertyDto> = (
      materialDefinition.materialProperties ?? []
    ).map((materialProperty) => ({
      classCode: this.resolveMaterialClass(materialProperty, materialClassById)
        .code,
      classDescription: this.findDescriptionByLanguage(
        this.resolveMaterialClass(materialProperty, materialClassById)
          .descriptions,
        languageCode,
      ),
      id: materialProperty.id,
      materialClassId: materialProperty.materialClassId,
      valueDescriptions: this.mapPropertyDescriptions(
        materialProperty.propertiesJson,
        this.resolveMaterialClass(materialProperty, materialClassById)
          .materialClassProperties,
        languageCode,
      ),
      values: materialProperty.propertiesJson ?? {},
    }));

    const storageLocations = properties.flatMap((property) => {
      const candidate = property.values.Storage_Locations;

      if (Array.isArray(candidate)) {
        return candidate
          .filter((value): value is string => typeof value === 'string')
          .map((value) => value.trim())
          .filter(Boolean);
      }

      return [];
    });

    return {
      code: materialDefinition.code,
      createdAt: materialDefinition.createdAt,
      description: this.findDescriptionByLanguage(
        materialDefinition.materialDescriptionByLanguages,
        languageCode,
      ),
      erpSource: materialDefinition.erpSource,
      id: materialDefinition.id,
      materialClasses,
      plant: materialDefinition.plant,
      properties,
      storageLocations,
      updatedAt: materialDefinition.updatedAt,
    };
  }

  private static findDescriptionByLanguage(
    items: Array<DescriptionByLanguageLike> | undefined,
    languageCode: string,
  ): string | undefined {
    return this.findPreferredDescription(items, languageCode)?.description;
  }

  private static parseJsonArray<T>(
    value: string | Array<T> | null | undefined,
  ): Array<T> {
    if (Array.isArray(value)) {
      return value;
    }

    if (typeof value !== 'string' || value.trim() === '') {
      return [];
    }

    try {
      const parsedValue: unknown = JSON.parse(value);
      return Array.isArray(parsedValue) ? (parsedValue as Array<T>) : [];
    } catch {
      return [];
    }
  }

  private static findPreferredDescription<T extends DescriptionByLanguageLike>(
    descriptions: Array<T> | undefined,
    languageCode?: string,
  ): T | undefined {
    const normalizedLanguageCode = this.normalizeLanguageCode(languageCode);

    return (
      descriptions?.find(
        (description) =>
          this.normalizeStoredLanguageCode(description.code) ===
          normalizedLanguageCode,
      ) ??
      (normalizedLanguageCode === 'EN'
        ? undefined
        : descriptions?.find(
            (description) =>
              this.normalizeStoredLanguageCode(description.code) === 'EN',
          )) ??
      descriptions?.[0]
    );
  }

  private static mapPropertyDescriptions(
    values: Record<string, unknown> | undefined,
    classProperties:
      | Array<{
          code: string;
          descriptions?: Array<DescriptionByLanguageLike>;
        }>
      | undefined,
    languageCode: string,
  ): Record<string, string> | undefined {
    const valueKeys = Object.keys(values ?? {});

    if (
      valueKeys.length === 0 ||
      classProperties === undefined ||
      classProperties.length === 0
    ) {
      return undefined;
    }

    const classPropertiesByNormalizedCode = new Map(
      classProperties.map((classProperty) => [
        this.normalizePropertyKey(classProperty.code),
        classProperty,
      ]),
    );

    const descriptions = Object.fromEntries(
      valueKeys.flatMap((valueKey) => {
        const matchingClassProperty = classPropertiesByNormalizedCode.get(
          this.normalizePropertyKey(valueKey),
        );
        const description = this.findDescriptionByLanguage(
          matchingClassProperty?.descriptions,
          languageCode,
        );

        return description !== undefined && description !== ''
          ? [[valueKey, description]]
          : [];
      }),
    );

    return Object.keys(descriptions).length > 0 ? descriptions : undefined;
  }

  private static normalizeLanguageCode(languageCode?: string): string {
    const normalizedLanguageCode = languageCode?.trim().toUpperCase();

    return normalizedLanguageCode !== undefined && normalizedLanguageCode !== ''
      ? normalizedLanguageCode
      : 'EN';
  }

  private static normalizePropertyKey(value: string): string {
    return value.replaceAll(/[^\dA-Za-z]/g, '').toLowerCase();
  }

  private static normalizeStoredLanguageCode(
    languageCode?: string,
  ): string | undefined {
    const normalizedLanguageCode = languageCode?.trim().toUpperCase();

    return normalizedLanguageCode !== undefined && normalizedLanguageCode !== ''
      ? normalizedLanguageCode
      : undefined;
  }

  private static resolveMaterialClass(
    materialProperty: MaterialPropertyRawDto,
    materialClassById: Map<number, MaterialClassRawDto>,
  ): MaterialClassRawDto {
    const maybeProperty = materialProperty as MaterialPropertyRawDto & {
      materialClass?: MaterialClassRawDto;
    };

    return (
      maybeProperty.materialClass ??
      materialClassById.get(materialProperty.materialClassId) ?? {
        code: '',
        id: materialProperty.materialClassId,
      }
    );
  }
}

