@Injectable()
export class MaterialDefinitionService {
  private static async mergeJsonPropertiesByPropertyId(
    manager: DataSource['manager'],
    propertyId: number,
    properties: Record<string, unknown>,
  ): Promise<WrappedResponse<undefined> | null> {
    const entries = Object.entries(properties);

    if (entries.length === 0) {
      return ResponseWrapper.error(
        STATUS_CODE.BAD_REQUEST,
        'At least one property must be provided for update',
      );
    }

    const parameters: Array<unknown> = [];
    let expression = 'properties_json';

    for (const [key, value] of entries) {
      if (!MaterialDefinitionService.isValidJsonModifyKey(key)) {
        return ResponseWrapper.error(
          STATUS_CODE.CONFLICT,
          `Invalid property key: ${key}. Only letters, numbers and underscore are allowed`,
        );
      }

      const index = parameters.length;
      if (value !== null && typeof value === 'object') {
        parameters.push(JSON.stringify(value));
        expression = `JSON_MODIFY(${expression}, '$.${key}', JSON_QUERY(@${index}))`;
      } else {
        parameters.push(value);
        expression = `JSON_MODIFY(${expression}, '$.${key}', @${index})`;
      }
    }

    const idIndex = parameters.length;
    parameters.push(propertyId);

    await manager.query(
      `UPDATE [isa95].[material_property] SET properties_json = ${expression} WHERE id = @${idIndex}`,
      parameters,
    );

    return ResponseWrapper.success(
      STATUS_CODE.OK,
      'Material property updated successfully',
    );
  }

  private static isValidJsonModifyKey(key: string): boolean {
    return /^\w+$/.test(key);
  }

  private static normalizePropertiesByClassId(
    uniqueMaterialClassIds: Array<number>,
    properties?: Array<MaterialDefinitionPropertyInputDto>,
  ):
    | Map<number, Record<string, unknown>>
    | WrappedResponse<MaterialDefinitionResponseDto | undefined> {
    const normalizedPropertiesByClassId = new Map<
      number,
      Record<string, unknown>
    >();

    for (const property of properties ?? []) {
      if (!uniqueMaterialClassIds.includes(property.materialClassId)) {
        // Return error with undefined data to match the expected type
        return ResponseWrapper.error(
          STATUS_CODE.BAD_REQUEST,
          `materialClassId ${property.materialClassId} must be present in materialClassIds`,
        );
      }

      normalizedPropertiesByClassId.set(property.materialClassId, {
        ...normalizedPropertiesByClassId.get(property.materialClassId),
        ...property.values,
      });
    }

    return normalizedPropertiesByClassId;
  }

  private static async getCurrentProperties(
    manager: DataSource['manager'],
    materialDefinitionId: number,
    plant: number,
  ): Promise<Array<MaterialProperty>> {
    return manager
      .createQueryBuilder(MaterialProperty, 'materialProperty')
      .select([
        'materialProperty.id',
        'materialProperty.materialClassId',
        'materialProperty.materialDefinitionId',
        'materialProperty.plant',
        'materialProperty.propertiesJson',
      ])
      .where('materialProperty.material_definition_id = :id', {
        id: materialDefinitionId,
      })
      .andWhere('materialProperty.plant = :plant', {
        plant,
      })
      .orderBy('materialProperty.id', 'ASC')
      .getMany();
  }

  private static async syncMaterialClassRelations(
    manager: DataSource['manager'],
    materialDefinitionId: number,
    plant: number,
    uniqueMaterialClassIds: Array<number>,
  ): Promise<void> {
    if (uniqueMaterialClassIds.length === 0) {
      await manager.delete(MaterialMaterialClass, {
        materialDefinitionId,
        plant,
      });
      return;
    }

    const currentRelations = await manager
      .createQueryBuilder(MaterialMaterialClass, 'materialMaterialClass')
      .select([
        'materialMaterialClass.id',
        'materialMaterialClass.materialClassId',
      ])
      .where('materialMaterialClass.material_definition_id = :id', {
        id: materialDefinitionId,
      })
      .andWhere('materialMaterialClass.plant = :plant', {
        plant,
      })
      .getMany();

    const currentClassIds = new Set(
      currentRelations.map((relation) => relation.materialClassId),
    );

    const materialClassIdsToAdd = uniqueMaterialClassIds.filter(
      (materialClassId) => !currentClassIds.has(materialClassId),
    );

    const relationIdsToDelete = currentRelations
      .filter(
        (relation) =>
          !uniqueMaterialClassIds.includes(relation.materialClassId),
      )
      .map((relation) => relation.id);

    if (relationIdsToDelete.length > 0) {
      await manager.delete(MaterialMaterialClass, relationIdsToDelete);
    }

    const relationsToCreate = materialClassIdsToAdd.map((materialClassId) =>
      manager.create(MaterialMaterialClass, {
        materialClassId,
        materialDefinitionId,
        plant,
      }),
    );

    if (relationsToCreate.length > 0) {
      await manager.save(relationsToCreate);
    }
  }

  private static async deleteObsoleteMaterialProperties(
    manager: DataSource['manager'],
    currentProperties: Array<MaterialProperty>,
    uniqueMaterialClassIds: Array<number>,
  ): Promise<void> {
    const propertyIdsToDelete = currentProperties
      .filter(
        (materialProperty) =>
          !uniqueMaterialClassIds.includes(materialProperty.materialClassId),
      )
      .map((materialProperty) => materialProperty.id);

    if (propertyIdsToDelete.length > 0) {
      await manager.delete(MaterialProperty, propertyIdsToDelete);
    }
  }

  private static async upsertMaterialProperties(
    manager: DataSource['manager'],
    materialDefinitionId: number,
    plant: number,
    currentProperties: Array<MaterialProperty>,
    normalizedPropertiesByClassId: Map<number, Record<string, unknown>>,
  ): Promise<WrappedResponse<undefined>> {
    const currentPropertiesByClassId = new Map(
      currentProperties.map((materialProperty) => [
        materialProperty.materialClassId,
        materialProperty,
      ]),
    );

    const results = await Promise.all(
      [...normalizedPropertiesByClassId].map(
        async ([materialClassId, values]) => {
          const existingProperty =
            currentPropertiesByClassId.get(materialClassId);

          if (existingProperty) {
            return MaterialDefinitionService.mergeJsonPropertiesByPropertyId(
              manager,
              existingProperty.id,
              values,
            );
          }

          await manager.save(
            manager.create(MaterialProperty, {
              materialClassId,
              materialDefinitionId,
              plant,
              propertiesJson: values,
            }),
          );

          return null;
        },
      ),
    );

    return (
      results.find((result) => result !== null) ??
      ResponseWrapper.success(
        STATUS_CODE.OK,
        'Material properties upserted successfully',
      )
    );
  }

  private static parseJsonArray<T>(value: unknown): Array<T> {
    if (Array.isArray(value)) {
      return value as Array<T>;
    }

    if (typeof value !== 'string' || value.trim() === '') {
      return [];
    }

    try {
      const parsedValue = JSON.parse(value) as unknown;
      return Array.isArray(parsedValue) ? (parsedValue as Array<T>) : [];
    } catch {
      return [];
    }
  }

  private static parseJsonObject(value: unknown): Record<string, unknown> {
    if (value != null && typeof value === 'object' && !Array.isArray(value)) {
      return value as Record<string, unknown>;
    }

    if (typeof value !== 'string' || value.trim() === '') {
      return {};
    }

    try {
      const parsedValue = JSON.parse(value) as unknown;

      if (
        parsedValue != null &&
        typeof parsedValue === 'object' &&
        !Array.isArray(parsedValue)
      ) {
        return parsedValue as Record<string, unknown>;
      }
    } catch {
      return {};
    }

    return {};
  }

  private static mapValueDescriptions(
    pairs: Array<Record<string, unknown>>,
  ): Record<string, string> | undefined {
    if (pairs.length === 0) {
      return undefined;
    }

    const valueDescriptions = Object.fromEntries(
      pairs.flatMap((pair) => {
        const key = typeof pair.key === 'string' ? pair.key : undefined;
        const value = typeof pair.value === 'string' ? pair.value : undefined;

        if (
          key == null ||
          key.trim() === '' ||
          value == null ||
          value.trim() === ''
        ) {
          return [];
        }

        return [[key, value]];
      }),
    );

    return Object.keys(valueDescriptions).length > 0
      ? valueDescriptions
      : undefined;
  }

  private static toAssignedClassProperty(
    row: Record<string, unknown>,
  ): MaterialDefinitionAssignedClassPropertyDto | undefined {
    if (row.propertyId == null) {
      return undefined;
    }

    const propertySemanticsJson =
      typeof row.propertySemanticsJson === 'string'
        ? MaterialDefinitionService.parseJsonObject(row.propertySemanticsJson)
        : undefined;

    return {
      code: MaterialDefinitionService.getOptionalString(row.propertyCode) ?? '',
      defaultValue: MaterialDefinitionService.getOptionalString(
        row.defaultValue,
      ),
      description: MaterialDefinitionService.getOptionalString(
        row.propertyDescription,
      ),
      externalMapping: MaterialDefinitionService.getOptionalString(
        row.externalMapping,
      ),
      id: Number(row.propertyId),
      isCustom: MaterialDefinitionService.getOptionalBoolean(row.isCustom),
      length: MaterialDefinitionService.getOptionalNumber(row.length),
      parentMaterialClassPropertyId:
        MaterialDefinitionService.getOptionalNumber(
          row.parentMaterialClassPropertyId,
        ),
      propertyDataTypeId: MaterialDefinitionService.getOptionalNumber(
        row.propertyDataTypeId,
      ),
      propertySemanticsJson,
      scale: MaterialDefinitionService.getOptionalNumber(row.scale),
    };
  }

  private static getOrCreateAssignedClassGroup(
    groupedByClass: Map<number, MaterialDefinitionAssignedClassPropertiesDto>,
    row: Record<string, unknown>,
  ): MaterialDefinitionAssignedClassPropertiesDto {
    const materialClassId = Number(row.materialClassId);
    const existingGroup = groupedByClass.get(materialClassId);

    if (existingGroup !== undefined) {
      return existingGroup;
    }

    const createdGroup: MaterialDefinitionAssignedClassPropertiesDto = {
      materialClassCode: MaterialDefinitionService.getOptionalString(
        row.materialClassCode,
      ),
      materialClassDescription: MaterialDefinitionService.getOptionalString(
        row.materialClassDescription,
      ),
      materialClassId,
      properties: [],
    };

    groupedByClass.set(materialClassId, createdGroup);

    return createdGroup;
  }

  private static getOptionalString(value: unknown): string | undefined {
    return typeof value === 'string' ? value : undefined;
  }

  private static getOptionalNumber(value: unknown): number | undefined {
    return typeof value === 'number' ? value : undefined;
  }

  private static getOptionalBoolean(value: unknown): boolean | undefined {
    return typeof value === 'boolean' ? value : undefined;
  }

  private readonly logger = new Logger(MaterialDefinitionService.name);

  public constructor(
    @InjectRepository(MaterialDefinition)
    private readonly materialDefinitionRepository: Repository<MaterialDefinition>,
    private readonly dataSource: DataSource,
  ) {}

  public async findAll(
    query: GetMaterialDefinitionsQueryDto,
  ): Promise<
    WrappedResponse<
      | MaterialDefinitionPaginatedResponseDto
      | MaterialDefinitionPaginationErrorData
      | undefined
    >
  > {
    try {
      const { limit, materialPropertyClassCodes, page, plant } = query;
      const offset = (page - 1) * limit;
      const normalizedLanguageCode = normalizeLanguageCode(query.languageCode);
      const classCodeStartIndex = 4;
      const hasMaterialPropertyClassCodes =
        materialPropertyClassCodes && materialPropertyClassCodes.length > 0;
      const materialPropertyClassCodePlaceholders =
        hasMaterialPropertyClassCodes
          ? materialPropertyClassCodes
              .map((_, index) => `@${classCodeStartIndex + index}`)
              .join(', ')
          : `''`;
      const materialClassCodeFilter = `AND mc2.code IN (${materialPropertyClassCodePlaceholders})`;
      const [countRows, rawResults] = await Promise.all([
        this.dataSource.query(
          `
      SELECT COUNT(1) AS total
      FROM isa95.material_definition md
      WHERE md.plant = @0
      `,
          [plant],
        ) as Promise<Array<{ total: number | string }>>,
        this.dataSource.query(
          `
      SELECT
        md.id,
        md.code,
        md.erp_source AS erpSource,
        md.plant,
        md.created_at AS createdAt,
        md.updated_at AS updatedAt,
        COALESCE(requestedMaterialDescription.description, englishMaterialDescription.description) AS description,
        (
          SELECT mc.id AS [materialClass.id], mc.code AS [materialClass.code]
          FROM isa95.material_material_class mmc
          INNER JOIN isa95.material_class mc ON mc.id = mmc.material_class_id
          WHERE mmc.material_definition_id = md.id
          FOR JSON PATH
        ) AS materialMaterialClasses,
        (
          SELECT
            mp.id,
            mp.material_class_id AS materialClassId,
            JSON_QUERY(mp.properties_json) AS propertiesJson,
            mc2.id AS [materialClass.id],
            mc2.code AS [materialClass.code]
          FROM isa95.material_property mp
          INNER JOIN isa95.material_class mc2 ON mc2.id = mp.material_class_id
          WHERE mp.material_definition_id = md.id
            ${materialClassCodeFilter}
          FOR JSON PATH
        ) AS materialProperties
      FROM isa95.material_definition md
      LEFT JOIN isa95.material_description_by_language requestedMaterialDescription
        ON requestedMaterialDescription.material_definition_id = md.id
        AND requestedMaterialDescription.code = @3
      LEFT JOIN isa95.material_description_by_language englishMaterialDescription
        ON englishMaterialDescription.material_definition_id = md.id
        AND englishMaterialDescription.code = 'EN'
      WHERE md.plant = @0
      ORDER BY md.code ASC, md.id ASC
      OFFSET @1 ROWS FETCH NEXT @2 ROWS ONLY
      `,
          [
            plant,
            offset,
            limit,
            normalizedLanguageCode,
            ...(hasMaterialPropertyClassCodes
              ? materialPropertyClassCodes
              : []),
          ],
        ) as Promise<Array<MaterialDefinitionListItemRawResponseDto>>,
      ]);

      const total = Number(countRows[0]?.total ?? 0);
      const availablePages = total === 0 ? 0 : Math.ceil(total / limit);

      if (rawResults.length === 0) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          'Material definitions do not exist',
          {
            availablePages,
            limit,
            page,
            total,
          },
        );
      }

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Material definitions retrieved successfully',
        {
          items: rawResults.map((item) =>
            MaterialDefinitionMapper.toResponseDtoFromListItem(
              item,
              query.languageCode,
            ),
          ),
          limit,
          page,
          total,
        },
      );
    } catch (error) {
      this.logger.error(
        `Failed to retrieve material definitions for plant ${query.plant}`,
        error instanceof Error ? error.stack : JSON.stringify(error),
      );

      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Unexpected server error',
      );
    }
  }

  public async findOne(
    id: number,
    languageCode = 'EN',
  ): Promise<WrappedResponse<MaterialDefinitionResponseDto | undefined>> {
    try {
      const normalizedLanguageCode = normalizeLanguageCode(languageCode);

      const rows = await this.dataSource.query(
        `
      SELECT TOP 1
        md.id,
        md.plant,
        md.code,
        md.erp_source AS erpSource,
        md.created_at AS createdAt,
        md.updated_at AS updatedAt,
        COALESCE(requestedMaterialDescription.description, englishMaterialDescription.description) AS description,
        (
          SELECT
            mc.id,
            mc.code,
            COALESCE(requestedClassDescription.description, englishClassDescription.description, mc.code) AS description
          FROM isa95.material_material_class mmc
          INNER JOIN isa95.material_class mc
            ON mc.id = mmc.material_class_id
          LEFT JOIN isa95.material_class_description requestedClassDescription
            ON requestedClassDescription.material_class_id = mc.id
            AND requestedClassDescription.code = @1
          LEFT JOIN isa95.material_class_description englishClassDescription
            ON englishClassDescription.material_class_id = mc.id
            AND englishClassDescription.code = 'EN'
          WHERE mmc.material_definition_id = md.id
          FOR JSON PATH
        ) AS materialClasses,
        (
          SELECT
            mp.id,
            mp.material_class_id AS materialClassId,
            mc.code AS classCode,
            COALESCE(requestedClassDescription.description, englishClassDescription.description, mc.code) AS classDescription,
            JSON_QUERY(mp.properties_json) AS [values],
            (
              SELECT
                propertyKey.[key] AS [key],
                COALESCE(requestedPropertyDescription.description, englishPropertyDescription.description, propertyKey.[key]) AS [value]
              FROM OPENJSON(mp.properties_json) propertyKey
              LEFT JOIN isa95.material_class_property mcp
                ON mcp.material_class_id = mp.material_class_id
                AND LOWER(mcp.code) = LOWER(propertyKey.[key] COLLATE DATABASE_DEFAULT)
              LEFT JOIN isa95.material_property_description requestedPropertyDescription
                ON requestedPropertyDescription.material_class_property_id = mcp.id
                AND requestedPropertyDescription.code = @1
              LEFT JOIN isa95.material_property_description englishPropertyDescription
                ON englishPropertyDescription.material_class_property_id = mcp.id
                AND englishPropertyDescription.code = 'EN'
              FOR JSON PATH
            ) AS valueDescriptionPairs
          FROM isa95.material_property mp
          INNER JOIN isa95.material_class mc
            ON mc.id = mp.material_class_id
          LEFT JOIN isa95.material_class_description requestedClassDescription
            ON requestedClassDescription.material_class_id = mc.id
            AND requestedClassDescription.code = @1
          LEFT JOIN isa95.material_class_description englishClassDescription
            ON englishClassDescription.material_class_id = mc.id
            AND englishClassDescription.code = 'EN'
          WHERE mp.material_definition_id = md.id
          FOR JSON PATH
        ) AS properties
      FROM isa95.material_definition md
      LEFT JOIN isa95.material_description_by_language requestedMaterialDescription
        ON requestedMaterialDescription.material_definition_id = md.id
        AND requestedMaterialDescription.code = @1
      LEFT JOIN isa95.material_description_by_language englishMaterialDescription
        ON englishMaterialDescription.material_definition_id = md.id
        AND englishMaterialDescription.code = 'EN'
      WHERE md.id = @0
      `,
        [id, normalizedLanguageCode],
      );

      const row = rows[0] as Record<string, unknown> | undefined;

      if (row === undefined) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Material definition with id ${id} does not exist`,
        );
      }

      const materialClasses = MaterialDefinitionService.parseJsonArray<
        Record<string, unknown>
      >(row.materialClasses).map((materialClass: Record<string, unknown>) => ({
        code: typeof materialClass.code === 'string' ? materialClass.code : '',
        description:
          typeof materialClass.description === 'string'
            ? materialClass.description
            : undefined,
        id: Number(materialClass.id),
      }));

      const properties = MaterialDefinitionService.parseJsonArray<
        Record<string, unknown>
      >(row.properties).map(
        (property: Record<string, unknown>): MaterialDefinitionPropertyDto => {
          const values = MaterialDefinitionService.parseJsonObject(
            property.values,
          );
          const valueDescriptionPairs =
            MaterialDefinitionService.parseJsonArray<Record<string, unknown>>(
              property.valueDescriptionPairs,
            );

          return {
            classCode:
              typeof property.classCode === 'string' ? property.classCode : '',
            classDescription:
              typeof property.classDescription === 'string'
                ? property.classDescription
                : undefined,
            id: Number(property.id),
            materialClassId: Number(property.materialClassId),
            valueDescriptions: MaterialDefinitionService.mapValueDescriptions(
              valueDescriptionPairs,
            ),
            values,
          };
        },
      );

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Material definition retrieved successfully',
        {
          code: String(row.code),
          createdAt: new Date(String(row.createdAt)),
          description:
            typeof row.description === 'string' ? row.description : undefined,
          erpSource: String(row.erpSource),
          id: Number(row.id),
          materialClasses,
          plant: Number(row.plant),
          properties,
          storageLocations: this.extractStorageLocations(properties),
          updatedAt: new Date(String(row.updatedAt)),
        },
      );
    } catch (error) {
      this.logger.error(
        `Failed to retrieve material definition ${id}`,
        error instanceof Error ? error.stack : JSON.stringify(error),
      );

      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Unexpected server error',
      );
    }
  }

  public async findAssignedClassProperties(
    id: number,
    languageCode = 'EN',
  ): Promise<
    WrappedResponse<
      Array<MaterialDefinitionAssignedClassPropertiesDto> | undefined
    >
  > {
    try {
      const materialDefinition =
        await this.materialDefinitionRepository.findOne({
          where: { id },
        });

      if (materialDefinition === null) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Material definition with id ${id} does not exist`,
        );
      }

      const normalizedLanguageCode = normalizeLanguageCode(languageCode);

      const rows = await this.dataSource.query(
        `
      SELECT
        mc.id AS materialClassId,
        mc.code AS materialClassCode,
        COALESCE(requestedClassDescription.description, englishClassDescription.description, mc.code) AS materialClassDescription,
        mcp.id AS propertyId,
        mcp.code AS propertyCode,
        COALESCE(requestedPropertyDescription.description, englishPropertyDescription.description, mcp.code) AS propertyDescription,
        mcp.is_custom AS isCustom,
        mcp.length,
        mcp.scale,
        mcp.external_mapping AS externalMapping,
        mcp.property_data_type_id AS propertyDataTypeId,
        mcp.parent_material_class_property_id AS parentMaterialClassPropertyId,
        mcp.property_semantics_json AS propertySemanticsJson
      FROM isa95.material_material_class mmc
      INNER JOIN isa95.material_class mc
        ON mc.id = mmc.material_class_id
      LEFT JOIN isa95.material_class_description requestedClassDescription
        ON requestedClassDescription.material_class_id = mc.id
        AND requestedClassDescription.code = @1
      LEFT JOIN isa95.material_class_description englishClassDescription
        ON englishClassDescription.material_class_id = mc.id
        AND englishClassDescription.code = 'EN'
      LEFT JOIN isa95.material_class_property mcp
        ON mcp.material_class_id = mc.id
      LEFT JOIN isa95.material_property_description requestedPropertyDescription
        ON requestedPropertyDescription.material_class_property_id = mcp.id
        AND requestedPropertyDescription.code = @1
      LEFT JOIN isa95.material_property_description englishPropertyDescription
        ON englishPropertyDescription.material_class_property_id = mcp.id
        AND englishPropertyDescription.code = 'EN'
      WHERE mmc.material_definition_id = @0
      ORDER BY mc.id ASC, mcp.id ASC
      `,
        [id, normalizedLanguageCode],
      );

      if (rows.length === 0) {
        return ResponseWrapper.success(
          STATUS_CODE.OK,
          'Assigned material class properties retrieved successfully',
          [],
        );
      }

      const groupedByClass = new Map<
        number,
        MaterialDefinitionAssignedClassPropertiesDto
      >();

      for (const row of rows as Array<Record<string, unknown>>) {
        const group = MaterialDefinitionService.getOrCreateAssignedClassGroup(
          groupedByClass,
          row,
        );
        const property = MaterialDefinitionService.toAssignedClassProperty(row);

        if (property !== undefined) {
          group.properties.push(property);
        }
      }

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Assigned material class properties retrieved successfully',
        [...groupedByClass.values()],
      );
    } catch (error) {
      this.logger.error(
        `Failed to retrieve assigned class properties for material definition ${id}`,
        error instanceof Error ? error.stack : JSON.stringify(error),
      );

      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Unexpected server error',
      );
    }
  }

  public async getSuggestions(
    query: MaterialDefinitionSearchQueryDto,
  ): Promise<
    WrappedResponse<Array<MaterialDefinitionSuggestionDto> | undefined>
  > {
    try {
      const normalizedSearchTerm = query.search.trim();

      if (normalizedSearchTerm === '') {
        return ResponseWrapper.error(
          STATUS_CODE.BAD_REQUEST,
          'Invalid input: search text cannot be empty',
        );
      }

      const normalizedSearch = `${normalizedSearchTerm.toUpperCase()}%`;
      const normalizedLanguageCode = normalizeLanguageCode(query.languageCode);
      const hasPlantFilter = query.plant !== undefined;
      const materialPlantPredicate = hasPlantFilter ? 'AND md.plant = @1' : '';
      const descriptionPlantPredicate = hasPlantFilter
        ? 'AND mdbl.plant = @1'
        : '';

      const suggestions: Array<MaterialDefinitionSuggestionDto> =
        await this.dataSource.query(
          `SELECT TOP (@0) *
         FROM (
      --This branch selects max 10 materials which match the pattern
           SELECT TOP (@0)
             md.id,
             md.code,
             dl.description
           FROM isa95.material_definition AS md
           OUTER APPLY (
             SELECT TOP 1 mdbl.description
             FROM isa95.material_description_by_language AS mdbl
             WHERE mdbl.material_definition_id = md.id
               AND (mdbl.code = 'EN' OR mdbl.code = @2)
             ORDER BY CASE WHEN mdbl.code = @2 THEN 1 ELSE 2 END
           ) AS dl
           WHERE  md.code LIKE @3
             ${materialPlantPredicate}
           ORDER BY md.plant, md.code

           UNION ALL --This in combination with GROUP BY keeps things simple and allows optimal index usage on each branch

    --This branch selects max 10 descriptions for specified language which match the pattern
           SELECT TOP (@0)
             mdbl.material_definition_id AS id,
             md.code,
             mdbl.description
           FROM isa95.material_description_by_language AS mdbl
           JOIN isa95.material_definition AS md
             ON md.id = mdbl.material_definition_id
           WHERE UPPER(mdbl.description) LIKE @3
             ${descriptionPlantPredicate}
             AND mdbl.code = @2
         ) AS res
         GROUP BY id, code, description`,
          [query.limit, query.plant, normalizedLanguageCode, normalizedSearch],
        );

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Material suggestions retrieved successfully',
        suggestions,
      );
    } catch (error) {
      this.logger.error(
        `Failed to retrieve material suggestions for search ${query.search}`,
        error instanceof Error ? error.stack : JSON.stringify(error),
      );

      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Unexpected server error',
      );
    }
  }

  public async syncMaterialClasses(
    id: number,
    materialClassIds: Array<number>,
    properties?: Array<MaterialDefinitionPropertyInputDto>,
  ): Promise<WrappedResponse<MaterialDefinitionResponseDto | undefined>> {
    try {
      const materialDefinition =
        await this.materialDefinitionRepository.findOne({
          where: { id },
        });

      if (materialDefinition === null) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Material definition with id ${id} does not exist`,
        );
      }

      const uniqueMaterialClassIds = [...new Set(materialClassIds)];
      const normalizedPropertiesByClassId =
        MaterialDefinitionService.normalizePropertiesByClassId(
          uniqueMaterialClassIds,
          properties,
        );

      if (!(normalizedPropertiesByClassId instanceof Map)) {
        // Always return the correct error type
        return ResponseWrapper.error(
          normalizedPropertiesByClassId.statusCode as
            | STATUS_CODE.BAD_REQUEST
            | STATUS_CODE.NOT_FOUND
            | STATUS_CODE.CONFLICT
            | STATUS_CODE.INTERNAL_SERVER_ERROR,
          normalizedPropertiesByClassId.messages,
        );
      }

      const transactionResult = await this.dataSource.transaction(
        async (manager) => {
          const currentProperties =
            await MaterialDefinitionService.getCurrentProperties(
              manager,
              id,
              materialDefinition.plant,
            );

          await MaterialDefinitionService.syncMaterialClassRelations(
            manager,
            id,
            materialDefinition.plant,
            uniqueMaterialClassIds,
          );

          await MaterialDefinitionService.deleteObsoleteMaterialProperties(
            manager,
            currentProperties,
            uniqueMaterialClassIds,
          );

          return MaterialDefinitionService.upsertMaterialProperties(
            manager,
            id,
            materialDefinition.plant,
            currentProperties,
            normalizedPropertiesByClassId,
          );
        },
      );

      if (transactionResult !== null) {
        return transactionResult;
      }

      return await this.findOne(id);
    } catch (error) {
      this.logger.error(
        `Failed to sync material classes for material definition ${id}`,
        error instanceof Error ? error.stack : JSON.stringify(error),
      );

      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Unexpected server error',
      );
    }
  }

  private extractStorageLocations(
    properties: Array<MaterialDefinitionPropertyDto>,
  ): Array<string> {
    const locations = properties.flatMap((property) => {
      return Object.entries(property.values)
        .filter(([key]) => key.toLowerCase().includes('storagelocation'))
        .flatMap(([, value]) => this.normalizeStorageLocationValue(value));
    });

    return [...new Set(locations)];
  }

  private normalizeStorageLocationValue(value: unknown): Array<string> {
    if (Array.isArray(value)) {
      return value.flatMap((item) => this.normalizeStorageLocationValue(item));
    }

    if (typeof value === 'string') {
      const normalizedValue = value.trim();
      return normalizedValue === '' ? [] : [normalizedValue];
    }

    if (value != null && typeof value === 'object' && 'value' in value) {
      return this.normalizeStorageLocationValue(
        (value as { value?: unknown }).value,
      );
    }

    return [];
  }
}

import { ApiProperty } from '@nestjs/swagger';
import { Type } from 'class-transformer';
import { IsInt, Max, Min } from 'class-validator';
import { MAX_SQL_INT } from './integer-range.constants';

export class IdParameterDto {
  @ApiProperty({
    description: 'Identifier',
    example: 1,
    maximum: MAX_SQL_INT,
    minimum: 1,
    type: Number,
  })
  @Type(() => Number)
  @IsInt()
  @Min(1)
  @Max(MAX_SQL_INT)
  public id!: number;
}

import { ApiProperty } from '@nestjs/swagger';

export class PropertyDataTypeResponseDto {
  @ApiProperty({ example: 1 })
  public id: number;

  @ApiProperty({ example: 'BOOLEAN' })
  public code: string;
}

export interface DescriptionByLanguageLike {
  code?: string | null;
  description: string;
}

export const defaultDescriptionLanguageCode = 'EN';

export const normalizeLanguageCode = (languageCode?: string): string => {
  const normalizedLanguageCode = languageCode?.trim().toUpperCase();
  return normalizedLanguageCode || defaultDescriptionLanguageCode;
};

const normalizeStoredLanguageCode = (
  languageCode?: string | null,
): string | undefined => {
  const normalizedLanguageCode = languageCode?.trim().toUpperCase();
  return normalizedLanguageCode || undefined;
};

export const findPreferredDescription = <T extends DescriptionByLanguageLike>(
  descriptions: Array<T> | undefined,
  languageCode?: string,
): T | undefined => {
  const normalizedLanguageCode = normalizeLanguageCode(languageCode);

  return (
    descriptions?.find(
      (description) =>
        normalizeStoredLanguageCode(description.code) ===
        normalizedLanguageCode,
    ) ??
    (normalizedLanguageCode === defaultDescriptionLanguageCode
      ? undefined
      : descriptions?.find(
          (description) =>
            normalizeStoredLanguageCode(description.code) ===
            defaultDescriptionLanguageCode,
        )) ??
    descriptions?.[0]
  );
};

export const resolveDescriptionLanguageCode = (
  description: Pick<DescriptionByLanguageLike, 'code'> | undefined,
  requestedLanguageCode?: string,
): string => {
  return (
    normalizeStoredLanguageCode(description?.code) ??
    normalizeLanguageCode(requestedLanguageCode)
  );
};

