import { PropertyDataTypeResponseDto } from './dtos/property-data-type-response.dto';
import { PropertyDataType } from './internal/property-data-type.entity';

@Injectable()
export class PropertyDataTypeService {
  private readonly logger = new Logger(PropertyDataTypeService.name);

  public constructor(
    @InjectRepository(PropertyDataType)
    private readonly propertyDataTypeRepository: Repository<PropertyDataType>,
  ) {}

  public async findAll(): Promise<
    WrappedResponse<Array<PropertyDataTypeResponseDto> | undefined>
  > {
    try {
      const propertyDataTypes = await this.propertyDataTypeRepository.find({
        order: { code: 'ASC' },
      });

      if (propertyDataTypes.length === 0) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          'Property data types do not exist',
        );
      }

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Property data types retrieved successfully',
        propertyDataTypes.length > 0
          ? propertyDataTypes.map((propertyDataType) => ({
              code: propertyDataType.code,
              id: propertyDataType.id,
            }))
          : undefined,
      );
    } catch (error) {
      this.logger.error(
        'Error retrieving property data types',
        error instanceof Error ? error.stack : undefined,
      );

      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Unexpected server error',
      );
    }
  }
}

