    PublishMessageModule,
    EventHubModule,
  ],
  providers: [MaterialService],
})
export class MaterialModule {}

import {
  BadRequestException,
  Injectable,
  InternalServerErrorException,
  NotFoundException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { In, Repository } from 'typeorm';
import { MaterialDescResponseDto } from './dtos/material-desc-response.dto';
import { MaterialIdsRequestDto } from './dtos/material-ids-request.dto';
import { MaterialRequestDto } from './dtos/material-request.dto';
import { MaterialResponseDto } from './dtos/material-response.dto';
import { MaterialWithDtlResponseDto } from './dtos/material-with-dtl-response.dto';
import { AppLogger } from '@/common/logger/app-logger';
import { EwmMaterialMessage } from '@/common/publish-message/interface/publish-event-ewm-material';
import { PublishMessageService } from '@/common/publish-message/publish-message.service';
import { EventhubService } from '@/config/eventhub/eventhub.service';
import { Material } from '@/modules/material/material.entity';

@Injectable()
export class MaterialService {
  private readonly logger = new AppLogger(MaterialService.name);

  public constructor(
    @InjectRepository(Material)
    private readonly materialRepo: Repository<Material>,
    private readonly publishMessageService: PublishMessageService,
    private readonly eventhubService: EventhubService,
  ) {}

  public async getMaterialById(
    materialId: string,
    sapServer: string,
  ): Promise<MaterialResponseDto> {
    try {
      const material = await this.materialRepo.findOne({
        where: { materialId, sapServer },
      });
      if (!material) {
        throw new NotFoundException(
          `Material with ID ${materialId}  not found on SAP Server ${sapServer} `,
        );
      }
      return material;
    } catch (error) {
      this.logger.error(
        `Failed to retrieve material: ${error.message}`,
        error.stack,
      );
      // Wrap and rethrow unexpected errors
      if (!(error instanceof NotFoundException)) {
        throw new InternalServerErrorException('Failed to retrieve material');
      }
      throw error;
    }
  }

  public async updateMaterial(
    updateData: MaterialRequestDto,
  ): Promise<MaterialResponseDto> {
    const { materialId, sapServer } = updateData;
    try {
      const material = await this.getMaterialById(materialId, sapServer);

      if (!material) {
        throw new NotFoundException('Material not found');
      }
      const isEwmPublish: boolean = updateData.ewmFlow !== material.ewmFlow;
      material.ewmFlow = updateData.ewmFlow;

      await this.materialRepo.save(material);
      if (isEwmPublish) {
        this.publishEwmMaterialMessage(
          `Material ${materialId} updated on ${sapServer}`,
        );
      }

      return material;
    } catch (error) {
      this.logger.error(
        `Failed to update material: ${error.message}`,
        error.stack,
      );
      // Wrap and rethrow unexpected errors
      if (!(error instanceof NotFoundException)) {
        throw new InternalServerErrorException('Failed to update material');
      }
      throw error;
    }
  }

  private async publishEwmMaterialMessage(message: string): Promise<void> {
    try {
      const plantMessage: EwmMaterialMessage = {
        message,
      };
      await this.publishMessageService.publishMessage(
        this.eventhubService.topicEwmMaterials,
        plantMessage,
      );
    } catch (error) {
      this.logger.error(
        `Failed to publish EWM material message: ${error.message}`,
        error.stack,
      );
      throw new InternalServerErrorException(
        'Failed to publish EWM material message',
      );
    }
  }

  public async getMaterialEwmFlow(
    sapServers: Array<string>,
  ): Promise<Record<string, Array<string>>> {
    try {
      if (!sapServers?.length) {
        throw new NotFoundException('SAP server list is empty');
      }

      const invalid = sapServers.filter(
        (s) => typeof s !== 'string' || !s.trim(),
      );
      if (invalid.length > 0) {
        throw new BadRequestException(
          `Invalid SAP server(s) provided: ${invalid.join(', ')}`,
        );
      }

      const rows = await this.materialRepo
        .createQueryBuilder('m')
        .select(['m.sap_server', 'm.material_id'])
        .where('m.sap_server IN (:...sapServers)', { sapServers })
        .andWhere('m.ewm_flow = 1')
        .getRawMany();

      const result: Record<string, Array<string>> = {};

      for (const row of rows) {
        if (!result[row.sap_server]) result[row.sap_server] = [];
        result[row.sap_server].push(row.material_id);
      }

      return result;
    } catch (error) {
      this.logger.error(
        `Failed to retrieve EWM Flow information for SAP servers [${sapServers}]: ${error.message}`,
      );
      return {};
    }
  }

  public async getAllMaterialWithDeteals(
    plant: string,
    sapServer: string,
  ): Promise<Array<MaterialWithDtlResponseDto>> {
    try {
      const material = await this.materialRepo
        .createQueryBuilder('material')
        .select([
          'DISTINCT material.material_id as materialId', // Ensure distinct materialId
          'material.sap_server as sapServer',
          'material.ewm_flow as ewmFlow',
          'material_dtl.plant as plant',
          'material_dtl.grouping_agv as groupingAGV',
          'material_dtl.kitmat as kitmat',
          'material_dtl.prodstrat as prodstrat',
          'material_dtl.sebango as sebango',
        ])
        .innerJoin(
          'material_storage_location',
          'ms',
          'ms.material_id = material.materialId AND ms.plant = :plant',
          { plant },
        )
        .leftJoin(
          'material_dtl',
          'material_dtl',
          'material_dtl.material_id = material.materialId AND material_dtl.plant = :plant',
          { plant },
        )
        // Filter by sap_server only on material table
        .where('material.sap_server = :sapServer', { sapServer })
        .getRawMany();

      if (!material || material.length === 0) {
        throw new NotFoundException(` no Materials with ID ${plant} not found`);
      }
      return material;
    } catch (error) {
      this.logger.error(
        `Failed to retrieve material: ${error.message}`,
        error.stack,
      );
      if (!(error instanceof NotFoundException)) {
        throw new InternalServerErrorException('Failed to retrieve material');
      }
      throw error;
    }
  }

  public async updateMaterialsBulk(
    plant: string,
    sapServer: string,
    updateDtos: Array<MaterialRequestDto>,
  ): Promise<Array<MaterialResponseDto>> {
    const materialIds = updateDtos.map((dto) => dto.materialId);
    const materials = await this.materialRepo.find({
      where: { materialId: In(materialIds), sapServer },
    });

    if (materials.length !== updateDtos.length) {
      const missingIds = materialIds.filter(
        (id) => !materials.some((matr) => matr.materialId === id),
      );
      throw new Error(
        `Some materials were not found for plant ${plant}: Missing IDs: ${missingIds.join(', ')}`,
      );
    }
    const allowedFields = new Set(['materialId', 'ewmFlow']);

    for (const [index, dto] of updateDtos.entries()) {
      // Get all keys in the provided DTO
      const providedFields = Object.keys(dto);

      // Check for any extra fields
      const extraFields = providedFields.filter(
        (field) => !allowedFields.has(field),
      );
      if (extraFields.length > 0) {
        throw new BadRequestException(
          `Invalid fields in request at index ${index}: ${extraFields.join(', ')}`,
        );
      }
    }
    try {
      // Update materials with provided fields
      const updatedMaterials = materials.map((material) => {
        const foundDto = updateDtos.find(
          (dto: MaterialRequestDto) => dto.materialId === material.materialId,
        );
        if (foundDto) {
          Object.assign(material, foundDto);
        }
        return material;
      });
      const chunkArray = (
        array: Array<MaterialResponseDto>,
        size: number,
      ): Array<Array<MaterialResponseDto>> => {
        const result: Array<Array<MaterialResponseDto>> = [];
        for (let index = 0; index < array.length; index += size) {
          result.push(array.slice(index, index + size));
        }
        return result;
      };
      const workcenterChunks = chunkArray(updatedMaterials, 100);
      const savePromises = workcenterChunks.map((chunk) =>
        this.materialRepo.save(chunk),
      );
      await Promise.all(savePromises);
      if (updatedMaterials.length > 0) {
        this.publishEwmMaterialMessage(`Materials updated`);
      }
      return updatedMaterials;
    } catch (error) {
      this.logger.error(
        `Failed to update  materials for  [plant: ${plant}  ]: ${error.message}`,
      );
      throw new InternalServerErrorException(
        `Failed to update  materials for [plant: ${plant}] , ${materialIds} `,
      );
    }
  }

  public async getMaterialsByIds(
    plant: string,
    sapServer: string,
    dto: MaterialIdsRequestDto,
  ): Promise<Array<MaterialDescResponseDto>> {
    try {
      const { materialIds } = dto;
      const rows = await this.materialRepo
        .createQueryBuilder('m')
        .select([
          'm.material_id as materialId',
          'm.material_desc as materialDesc',
        ])
        .leftJoin(
          'material_dtl',
          'dtl',
          'dtl.material_id = m.materialId AND dtl.plant = :plant',
          { plant },
        )
        .where('m.materialId IN (:...materialIds)', { materialIds })
        .andWhere('m.sap_server =:sapServer', { sapServer })
        .getRawMany<{ materialId: string; materialDesc: string | null }>();

      return rows.map((row) => ({
        materialId: row.materialId,
        materialDesc: row.materialDesc,
      }));
    } catch (error: unknown) {
      const caughtError = error as Error;
      this.logger.error(
        `Failed to retrieve materials by IDs: ${caughtError.message}`,
        caughtError.stack,
      );
      throw new InternalServerErrorException(
        'Failed to retrieve materials by IDs',
      );
    }
  }

  public async getMaterialIdsByPlantAndSapServer(
    plant: string,
    sapServer: string,
  ): Promise<Array<MaterialDescResponseDto>> {
    try {
      const rows = await this.materialRepo
        .createQueryBuilder('m')
        .select([
          'm.material_id as materialId',
          'm.material_desc as materialDesc',
        ])
        .innerJoin(
          'material_dtl',
          'dtl',
          'dtl.material_id = m.materialId AND dtl.plant = :plant',
          { plant },
        )
        .where('m.sap_server = :sapServer', { sapServer })
        .getRawMany<{ materialId: string; materialDesc: string | null }>();

      return rows.map((row) => ({
        materialId: row.materialId,
        materialDesc: row.materialDesc,
      }));
    } catch (error: unknown) {
      const caughtError = error as Error;
      this.logger.error(
        `Failed to retrieve material IDs for plant ${plant} and SAP server ${sapServer}: ${caughtError.message}`,
        caughtError.stack,
      );
      throw new InternalServerErrorException(
        'Failed to retrieve material IDs by plant and SAP server',
      );
    }
  }
}

