import { Injectable } from '@nestjs/common';

@Injectable()
export class HealthStateService {
  private readonly livenessStallThresholdMs: number;

  private fatalErrorReason: string | null = null;

  private eventLoopHeartbeatAt = Date.now();

  public constructor() {
    const parsed = Number(process.env.HEALTH_LIVENESS_STALL_THRESHOLD_MS);
    this.livenessStallThresholdMs =
      Number.isFinite(parsed) && parsed > 0 ? parsed : 300_000;

    setInterval(() => {
      this.eventLoopHeartbeatAt = Date.now();
    }, 15_000).unref();
  }

  public markFatalError(reason: string): void {
    this.fatalErrorReason = reason;
  }

  public isLivenessHealthy(): { ok: boolean; reason?: string } {
    if (this.fatalErrorReason) {
      return { ok: false, reason: this.fatalErrorReason };
    }

    const stalledForMs = Date.now() - this.eventLoopHeartbeatAt;
    if (stalledForMs > this.livenessStallThresholdMs) {
      return {
        ok: false,
        reason: `Event loop heartbeat stale for ${stalledForMs}ms`,
      };
    }

    return { ok: true };
  }
}

import { Injectable } from '@nestjs/common';
import {
  HealthCheckError,
  HealthIndicator,
  HealthIndicatorResult,
} from '@nestjs/terminus';

const DEFAULT_TIMEOUT_MS = 2000;

@Injectable()
export class DaprHealthIndicator extends HealthIndicator {
  private static resolveDaprPort(): number {
    const raw = process.env.DAPR_HTTP_PORT as string;
    const parsed = Number(raw);
    if (!Number.isInteger(parsed) || parsed <= 0 || parsed > 65_535) {
      throw new Error(
        `Invalid DAPR_HTTP_PORT: "${raw}" is not a valid port number`,
      );
    }
    return parsed;
  }

  public async isHealthy(key: string): Promise<HealthIndicatorResult> {
    if (!process.env.DAPR_HTTP_PORT) {
      return this.getStatus(key, true, { skipped: true });
    }

    const port = DaprHealthIndicator.resolveDaprPort();
    const url = `http://127.0.0.1:${port}/v1.0/healthz`;

    try {
      const response = await fetch(url, {
        signal: AbortSignal.timeout(DEFAULT_TIMEOUT_MS),
      });
      if (!response.ok) {
        throw new Error(`Dapr sidecar returned status ${response.status}`);
      }
      return this.getStatus(key, true, { url });
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      throw new HealthCheckError(
        'Dapr sidecar is not healthy',
        this.getStatus(key, false, { url, message }),
      );
    }
  }
}

import { Injectable } from '@nestjs/common';
import {
  HealthCheckError,
  HealthIndicator,
  HealthIndicatorResult,
} from '@nestjs/terminus';
import { HealthStateService } from '@/modules/probes/health-state.service';

// Validate against actual container memory allocation before enabling heap check
// Const HEAP_LIMIT_BYTES = 300 * 1024 * 1024;

@Injectable()
export class LivenessHealthIndicator extends HealthIndicator {
  public constructor(private readonly healthState: HealthStateService) {
    super();
  }

  public isHealthy(key: string): HealthIndicatorResult {
    const stall = this.healthState.isLivenessHealthy();

    const details = {
      ...(stall.reason ? { eventLoop: stall.reason } : {}),
    };

    if (!stall.ok) {
      throw new HealthCheckError(
        stall.reason ?? 'Liveness check failed',
        this.getStatus(key, false, details),
      );
    }

    return this.getStatus(key, true, details);
  }
}

import { Injectable } from '@nestjs/common';
import {
  HealthCheckError,
  HealthIndicator,
  HealthIndicatorResult,
} from '@nestjs/terminus';
import { InjectDataSource } from '@nestjs/typeorm';
import { DataSource } from 'typeorm';
import { BootstrapState } from '@/modules/probes/bootstrap-state';
import { MssqlDatabaseChecker } from '@/providers/database/mssql/mssql.database.checker';

@Injectable()
export class StartupHealthIndicator extends HealthIndicator {
  public constructor(
    private readonly bootstrapState: BootstrapState,
    private readonly databaseChecker: MssqlDatabaseChecker,
    @InjectDataSource()
    private readonly dataSource: DataSource,
  ) {
    super();
  }

  public async isHealthy(key: string): Promise<HealthIndicatorResult> {
    const dataSourceInitialized = this.dataSource.isInitialized;
    const bootstrapReady = this.bootstrapState.isReady;

    const pendingMigrations = await this.checkPendingMigrations(
      key,
      bootstrapReady,
      dataSourceInitialized,
    );

    const healthy =
      bootstrapReady && dataSourceInitialized && !pendingMigrations;

    const details = {
      bootstrapReady,
      dataSourceInitialized,
      pendingMigrations,
    };

    if (!healthy) {
      throw new HealthCheckError(
        'Application is not fully started',
        this.getStatus(key, false, details),
      );
    }

    return this.getStatus(key, true, details);
  }

  private async checkPendingMigrations(
    key: string,
    bootstrapReady: boolean,
    dataSourceInitialized: boolean,
  ): Promise<boolean> {
    try {
      return this.databaseChecker.pendingMigrations();
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      throw new HealthCheckError(
        'Startup probe failed to evaluate migrations',
        this.getStatus(key, false, {
          bootstrapReady,
          dataSourceInitialized,
          message,
        }),
      );
    }
  }
}

import {
  HealthCheckError,
  TerminusModule,
  TypeOrmHealthIndicator,
} from '@nestjs/terminus';
import { Test, TestingModule } from '@nestjs/testing';
import { getDataSourceToken } from '@nestjs/typeorm';
import { DataSource } from 'typeorm';
import { BootstrapState } from '@/modules/probes/bootstrap-state';
import { DaprHealthIndicator } from '@/modules/probes/indicators/dapr.health-indicator';
import { LivenessHealthIndicator } from '@/modules/probes/indicators/liveness.health-indicator';
import { StartupHealthIndicator } from '@/modules/probes/indicators/startup.health-indicator';
import { ProbesController } from '@/modules/probes/probes.controller';
import { MssqlDatabaseChecker } from '@/providers/database/mssql/mssql.database.checker';

describe('ProbesController', () => {
  let controller: ProbesController;
  let bootstrapState: BootstrapState;
  let databaseIndicator: { pingCheck: jest.Mock };
  let livenessIndicator: { isHealthy: jest.Mock };
  let daprIndicator: { isHealthy: jest.Mock };
  let databaseChecker: { pendingMigrations: jest.Mock };
  let dataSource: { isInitialized: boolean };

  beforeEach(async () => {
    databaseIndicator = { pingCheck: jest.fn() };
    livenessIndicator = { isHealthy: jest.fn() };
    daprIndicator = { isHealthy: jest.fn() };
    databaseChecker = { pendingMigrations: jest.fn() };
    dataSource = { isInitialized: true };

    const module: TestingModule = await Test.createTestingModule({
      controllers: [ProbesController],
      imports: [TerminusModule],
      providers: [
        BootstrapState,
        StartupHealthIndicator,
        { provide: TypeOrmHealthIndicator, useValue: databaseIndicator },
        { provide: LivenessHealthIndicator, useValue: livenessIndicator },
        { provide: DaprHealthIndicator, useValue: daprIndicator },
        { provide: MssqlDatabaseChecker, useValue: databaseChecker },
        { provide: getDataSourceToken(), useValue: dataSource as DataSource },
      ],
    }).compile();

    controller = module.get(ProbesController);
    bootstrapState = module.get(BootstrapState);

    delete process.env.DAPR_HTTP_PORT;
  });

  afterEach(() => {
    delete process.env.DAPR_HTTP_PORT;
  });

  describe('GET /probes/health (legacy)', () => {
    it('returns the static OK message', () => {
      expect(controller.getHello()).toBe('mesx/master-api [OK]');
    });
  });

  describe('GET /probes/startup', () => {
    it('returns 503 when bootstrap is not ready', async () => {
      databaseChecker.pendingMigrations.mockResolvedValue(false);

      await expect(controller.checkStartup()).rejects.toBeDefined();
    });

    it('returns 503 when migrations are still pending', async () => {
      bootstrapState.markReady();
      databaseChecker.pendingMigrations.mockResolvedValue(true);

      await expect(controller.checkStartup()).rejects.toBeDefined();
    });

    it('returns ok when bootstrap is ready and no pending migrations', async () => {
      bootstrapState.markReady();
      databaseChecker.pendingMigrations.mockResolvedValue(false);

      const result = await controller.checkStartup();
      expect(result.status).toBe('ok');
      expect(result.info?.startup.status).toBe('up');
    });
  });

  describe('GET /probes/liveness', () => {
    it('returns ok when liveness check passes', async () => {
      livenessIndicator.isHealthy.mockReturnValue({
        liveness: { status: 'up' },
      });

      const result = await controller.checkLiveness();
      expect(result.status).toBe('ok');
      expect(livenessIndicator.isHealthy).toHaveBeenCalledWith('liveness');
    });

    it('returns error when liveness check fails', async () => {
      livenessIndicator.isHealthy.mockImplementation(() => {
        throw new HealthCheckError('liveness', {
          liveness: { status: 'down' },
        });
      });

      await expect(controller.checkLiveness()).rejects.toBeDefined();
    });
  });

  describe('GET /probes/readiness', () => {
    it('returns ok when DB is reachable and Dapr sidecar is not configured (self-skipped)', async () => {
      databaseIndicator.pingCheck.mockResolvedValue({
        database: { status: 'up' },
      });
      daprIndicator.isHealthy.mockResolvedValue({
        dapr: { status: 'up', skipped: true },
      });

      const result = await controller.checkReadiness();
      expect(result.status).toBe('ok');
      expect(databaseIndicator.pingCheck).toHaveBeenCalled();
      expect(daprIndicator.isHealthy).toHaveBeenCalledWith('dapr');
    });

    it('returns error when DB ping fails', async () => {
      databaseIndicator.pingCheck.mockImplementation(() => {
        throw new HealthCheckError('db', { database: { status: 'down' } });
      });

      await expect(controller.checkReadiness()).rejects.toBeDefined();
    });

    it('checks Dapr when DAPR_HTTP_PORT is set', async () => {
      process.env.DAPR_HTTP_PORT = '3500';
      databaseIndicator.pingCheck.mockResolvedValue({
        database: { status: 'up' },
      });
      daprIndicator.isHealthy.mockResolvedValue({ dapr: { status: 'up' } });

      const result = await controller.checkReadiness();
      expect(result.status).toBe('ok');
      expect(daprIndicator.isHealthy).toHaveBeenCalledWith('dapr');
    });

    it('returns error when Dapr is unreachable', async () => {
      process.env.DAPR_HTTP_PORT = '3500';
      databaseIndicator.pingCheck.mockResolvedValue({
        database: { status: 'up' },
      });
      daprIndicator.isHealthy.mockImplementation(() => {
        throw new HealthCheckError('dapr', { dapr: { status: 'down' } });
      });

      await expect(controller.checkReadiness()).rejects.toBeDefined();
    });
  });
});

import { Controller, Get } from '@nestjs/common';
import { ApiOperation, ApiTags } from '@nestjs/swagger';
import {
  HealthCheck,
  HealthCheckResult,
  HealthCheckService,
  HealthIndicatorResult,
  TypeOrmHealthIndicator,
} from '@nestjs/terminus';
import { DaprHealthIndicator } from '@/modules/probes/indicators/dapr.health-indicator';
import { LivenessHealthIndicator } from '@/modules/probes/indicators/liveness.health-indicator';
import { StartupHealthIndicator } from '@/modules/probes/indicators/startup.health-indicator';

const DB_PING_TIMEOUT_MS = 2000;

@ApiTags('Probes')
@Controller('probes')
export class ProbesController {
  private readonly healthMessage = 'mesx/master-api [OK]';

  public constructor(
    private readonly health: HealthCheckService,
    private readonly database: TypeOrmHealthIndicator,
    private readonly liveness: LivenessHealthIndicator,
    private readonly dapr: DaprHealthIndicator,
    private readonly startup: StartupHealthIndicator,
  ) {}

  @Get('health')
  @ApiOperation({
    deprecated: true,
    summary: 'Legacy health endpoint (use /probes/liveness instead).',
  })
  public getHello(): string {
    return this.healthMessage;
  }

  @Get('startup')
  @HealthCheck()
  @ApiOperation({
    summary:
      'Startup probe — succeeds once the app has finished bootstrap, the DB DataSource is initialized, and there are no pending migrations.',
  })
  public async checkStartup(): Promise<HealthCheckResult> {
    return this.health.check([
      (): Promise<HealthIndicatorResult> => this.startup.isHealthy('startup'),
    ]);
  }

  @Get('liveness')
  @HealthCheck()
  @ApiOperation({
    summary:
      'Liveness probe — verifies the process is responsive, the heap is below threshold, and the event loop is not stalled.',
  })
  public async checkLiveness(): Promise<HealthCheckResult> {
    return this.health.check([
      (): HealthIndicatorResult => this.liveness.isHealthy('liveness'),
    ]);
  }

  @Get('readiness')
  @HealthCheck()
  @ApiOperation({
    summary:
      'Readiness probe — verifies that downstream dependencies (database, Dapr sidecar) are reachable. Dapr check is skipped when DAPR_HTTP_PORT is not set.',
  })
  public async checkReadiness(): Promise<HealthCheckResult> {
    return this.health.check([
      (): Promise<HealthIndicatorResult> =>
        this.database.pingCheck('database', { timeout: DB_PING_TIMEOUT_MS }),
      (): Promise<HealthIndicatorResult> => this.dapr.isHealthy('dapr'),
    ]);
  }
}

import { Global, Module } from '@nestjs/common';
import { TerminusModule } from '@nestjs/terminus';
import { BootstrapState } from '@/modules/probes/bootstrap-state';
import { HealthStateService } from '@/modules/probes/health-state.service';
