/**
 * Pads a number with leading zeros to the specified length.
 * @param n The number to pad.
 * @param l The desired length of the output string.
 * @returns The padded number as a string.
 */
export function pad(n: number, l: number): string {
  return n.toString().padStart(l, '0');
}

/**
 * Extracts the date in yyyyMMdd format from a Date object.
 * @param d The Date object to extract the date from.
 * @returns The date as a string in yyyyMMdd format.
 */
export function extractDate(d: Date): string {
  return `${d.getUTCFullYear()}${pad(d.getUTCMonth() + 1, 2)}${pad(d.getUTCDate(), 2)}`;
}

/**
 * Extracts the time in HHmmss format from a Date object.
 * @param d The Date object to extract the time from.
 * @returns The time as a string in HHmmss format.
 */
export function extractTime(d: Date): string {
  return `${pad(d.getUTCHours(), 2)}${pad(d.getUTCMinutes(), 2)}${pad(d.getUTCSeconds(), 2)}`;
}

export interface ShiftContext {
  shift: number;
  startDatetime: string;
  endDatetime: string;
}

export interface ShiftContextResult {
  currentShift: ShiftContext | null;
  previousShift: ShiftContext | null;
  previousPreviousShift: ShiftContext | null;
}

import {
  Controller,
  Get,
  Res,
  HttpStatus,
  UseFilters,
  Query,
  UsePipes,
  ValidationPipe,
} from '@nestjs/common';
import { ApiTags, ApiOperation, ApiResponse } from '@nestjs/swagger';
import { Response } from 'express';
import { GetShiftContextDto } from './dtos/get-shift-context.dto';
import { ShiftDetailsService } from './shift-details.service';
import { MesGenericErrorFilter } from '@/common/filters/mes-generic-error.filter';

@ApiTags('ShiftDetails')
@Controller('shift-details')
@UsePipes(
  new ValidationPipe({
    forbidNonWhitelisted: true,
    transform: true,
    whitelist: true,
  }),
)
@UseFilters(MesGenericErrorFilter)
export class ShiftDetailsController {
  public constructor(
    private readonly shiftDetailsService: ShiftDetailsService,
  ) {}

  @ApiOperation({
    summary: 'Get current and previous shifts for a workcenter and date',
  })
  @ApiResponse({
    description:
      'Returns the current, previous, and previous-2 shifts for the given workcenter and date.',
    status: 200,
    schema: {
      example: {
        currentShift: {
          shift: 2,
          startDatetime: '2025-08-11T14:00:00Z',
          endDatetime: '2025-08-11T22:00:00Z',
        },
        previousShift: {
          shift: 1,
          startDatetime: '2025-08-11T06:00:00Z',
          endDatetime: '2025-08-11T14:00:00Z',
        },
        previousPreviousShift: {
          shift: 3,
          startDatetime: '2025-08-10T22:00:00Z',
          endDatetime: '2025-08-11T06:00:00Z',
        },
      },
    },
  })
  @ApiResponse({ description: 'Not found.', status: 404 })
  @Get('/shift-context')
  public async getShiftContext(
    @Res() response: Response,
    @Query() request: GetShiftContextDto,
  ): Promise<Response> {
    // Parse date as UTC
    const date = new Date(request.date);
    if (Number.isNaN(date.getTime())) {
      return response
        .status(HttpStatus.BAD_REQUEST)
        .json({ message: 'Invalid date format' });
    }
    const result = await this.shiftDetailsService.getShiftContext(
      Number(request.plantId),
      request.workcenterId,
      date,
    );
    if (result !== undefined) {
      const responseObject = {
        plant: Number(request.plantId),
        workcenterId: request.workcenterId,
        ...result,
      };

      return response.status(HttpStatus.OK).json(responseObject);
    }
    return response.status(HttpStatus.OK).json({
      message: `No current or previous shifts found for plant: ${request.plantId}, and workcenter: ${request.workcenterId}`,
    });
  }
}

