import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { LessThanOrEqual, MoreThanOrEqual, Repository } from 'typeorm';
import {
  ShiftContext,
  ShiftContextResult,
} from './interfaces/shift-context.interface';
import { ShiftDetails } from './shift-details.entity';
import { AppLogger } from '@/common/logger/app-logger';

@Injectable()
export class ShiftDetailsService {
  private readonly logger = new AppLogger(ShiftDetailsService.name);

  public constructor(
    @InjectRepository(ShiftDetails)
    private readonly shiftDetailsRepo: Repository<ShiftDetails>,
  ) {}

  /**
   * Returns the current, previous, and previous-2 shifts for a workcenter and plant at a given UTC datetime.
   * @param plantId Plant ID
   * @param workcenterId Workcenter ID
   * @param now Date object (UTC)
   * @returns ShiftContextResult
   */
  public async getShiftContext(
    plantId: number,
    workcenterId: string,
    now: Date,
  ): Promise<ShiftContextResult | undefined> {
    try {
      const shifts = await this.shiftDetailsRepo.find({
        where: {
          plant: plantId,
          workCenterId: workcenterId,
          startDateTime: LessThanOrEqual(now),
          endDateTime: MoreThanOrEqual(now),
        },
        order: { startDateTime: 'DESC' },
        take: 1,
      });
      if (shifts.length === 0) {
        return undefined;
      }

      const currentShift: ShiftContext = {
        shift: shifts[0].shift,
        startDatetime: shifts[0].startDateTime.toISOString(),
        endDatetime: shifts[0].endDateTime.toISOString(),
      };

      return {
        currentShift,
        previousShift: null,
        previousPreviousShift: null,
      };
    } catch {
      return undefined;
    }
  }
}

