    required: true,
    description: 'Plant ID',
  })
  @ApiQuery({
    name: 'poolstock',
    type: Boolean,
    required: true,
    description: 'Filter by poolstock ',
  })
  @ApiOkResponse({
    description: 'List of storage location IDs',
    type: GetStorageLocationResponseDto,
  })
  public async getStorageLocationByPlantAndPoolstock(
    @Query('plant') plant: number,
    @Query('poolstock') poolstock: string,
  ): Promise<GetStorageLocationResponseDto> {
    try {
      const isPoolstock = poolstock === 'true';

      const ids =
        await this.storageLocationSer.getStorageLocationIdsByPlantAndPoolStock(
          plant,
          isPoolstock,
        );

      return {
        storageLocationIds: ids,
      };
    } catch (error) {
      throw new Error(
        `Failed to retrieve storage location IDs: ${error instanceof Error ? error.message : ''}`,
      );
    }
  }
}

